// src/firebase/config.js - Improved Firebase configuration
import { initializeApp } from 'firebase/app';
import { getFirestore } from 'firebase/firestore';

// Import centralized configuration
import { FIREBASE_CONFIG } from '../config/config.js';

// Fallback configuration with environment variables for backward compatibility
const firebaseConfig = {
  apiKey: FIREBASE_CONFIG.apiKey || process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain: FIREBASE_CONFIG.authDomain || process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId: FIREBASE_CONFIG.projectId || process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: FIREBASE_CONFIG.storageBucket || process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: FIREBASE_CONFIG.messagingSenderId || process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId: FIREBASE_CONFIG.appId || process.env.REACT_APP_FIREBASE_APP_ID
};

// Validate configuration
const validateFirebaseConfig = (config) => {
  const requiredFields = ['apiKey', 'projectId'];
  const missingFields = requiredFields.filter(field => !config[field]);
  
  if (missingFields.length > 0) {
    console.error('❌ Missing Firebase configuration fields:', missingFields);
    console.log('💡 Update src/config/config.js with your Firebase credentials');
    throw new Error(`Firebase configuration missing: ${missingFields.join(', ')}`);
  }
  
  console.log('✅ Firebase configuration validated');
  console.log('🔍 Project ID:', config.projectId);
};

// Validate before initializing
validateFirebaseConfig(firebaseConfig);

// Initialize Firebase
let app;
let db;

try {
  app = initializeApp(firebaseConfig);
  console.log('✅ Firebase app initialized successfully');
  
  // Initialize Firestore
  db = getFirestore(app);
  console.log('✅ Firestore initialized successfully');
} catch (error) {
  console.error('❌ Firebase initialization failed:', error);
  throw error;
}

export { db };
export default app;