// Translation helper functions
export const translateLanguage = (language, targetLang) => {
  if (!language) return language;
  
  const translations = languageTranslations.languages[targetLang];
  return translations?.[language] || language;
};

export const translateFormat = (format, targetLang) => {
  if (!format) return format;
  
  const translations = languageTranslations.formats[targetLang];
  return translations?.[format] || format;
};

export const translateCondition = (condition, targetLang) => {
  if (!condition) return condition;
  
  const translations = languageTranslations.conditions[targetLang];
  return translations?.[condition] || condition;
};

// Get language options for form selects
export const getLanguageOptions = (currentLang) => {
  const languages = Object.keys(languageTranslations.languages.en);
  return languages.map(lang => ({
    value: lang,
    label: languageTranslations.languages[currentLang]?.[lang] || lang
  })).sort((a, b) => a.label.localeCompare(b.label));
};

// Get format options for form selects
export const getFormatOptions = (currentLang) => {
  const formats = Object.keys(languageTranslations.formats.en);
  return formats.map(format => ({
    value: format,
    label: languageTranslations.formats[currentLang]?.[format] || format
  }));
};

// Get condition options for form selects
export const getConditionOptions = (currentLang) => {
  const conditions = Object.keys(languageTranslations.conditions.en);
  return conditions.map(condition => ({
    value: condition,
    label: languageTranslations.conditions[currentLang]?.[condition] || condition
  }));
};