import React, { useState, useEffect } from 'react';
import { LanguageProvider } from './contexts/LanguageContext';
import { PatronAuthProvider } from './contexts/PatronAuthContext';
import PublicCatalog from './components/PublicCatalog';
import AdminDashboard from './components/AdminDashboard';
import Login from './components/Login';
import SEOHelmet from './components/SEOHelmet';

console.log('Firebase Config:', {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY?.substring(0, 10) + '...',
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID
});

function App() {
  const [view, setView] = useState('public'); // 'public', 'login', 'admin'
  const [currentSearchQuery, setCurrentSearchQuery] = useState('');
  const [selectedBook, setSelectedBook] = useState(null);

  // Handle URL parameters for SEO-friendly URLs
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const searchParam = urlParams.get('search');
    const bookParam = urlParams.get('book');
    const langParam = urlParams.get('lang');
    
    if (searchParam) {
      setCurrentSearchQuery(searchParam);
    }
    
    // Handle language switching from URL
    if (langParam && (langParam === 'uk' || langParam === 'en')) {
      // This would integrate with your LanguageContext
      // You might want to add a method to set language from URL
    }
  }, []);

  // Update URL when search changes (for SEO-friendly URLs)
  const updateSearchURL = (searchQuery) => {
    setCurrentSearchQuery(searchQuery);
    const url = new URL(window.location);
    if (searchQuery) {
      url.searchParams.set('search', searchQuery);
    } else {
      url.searchParams.delete('search');
    }
    window.history.replaceState({}, '', url);
  };

  const handleAdminLogin = () => {
    setView('login');
  };

  const handleLoginSuccess = () => {
    setView('admin');
  };

  const handleLogout = () => {
    setView('public');
  };

  const handleLoginCancel = () => {
    setView('public');
  };

  // Generate canonical URL based on current state
  const generateCanonicalURL = () => {
    const baseURL = window.location.origin;
    const params = new URLSearchParams();
    
    if (currentSearchQuery) {
      params.set('search', currentSearchQuery);
    }
    
    return `${baseURL}${params.toString() ? '?' + params.toString() : ''}`;
  };

  return (
    <LanguageProvider>
      <PatronAuthProvider>
        <div className="App">
          {/* SEO Component - dynamically updates meta tags */}
          <SEOHelmet 
            currentView={view}
            searchQuery={currentSearchQuery}
            bookData={selectedBook}
            canonicalUrl={generateCanonicalURL()}
          />

          {view === 'public' && (
            <PublicCatalog 
              onAdminClick={handleAdminLogin}
              onSearchChange={updateSearchURL}
              onBookSelect={setSelectedBook}
              initialSearchQuery={currentSearchQuery}
            />
          )}
          
          {view === 'login' && (
            <>
              <PublicCatalog 
                onAdminClick={handleAdminLogin}
                onSearchChange={updateSearchURL}
                onBookSelect={setSelectedBook}
                initialSearchQuery={currentSearchQuery}
              />
              <Login onLogin={handleLoginSuccess} onCancel={handleLoginCancel} />
            </>
          )}
          
          {view === 'admin' && (
            <AdminDashboard onLogout={handleLogout} />
          )}
        </div>
      </PatronAuthProvider>
    </LanguageProvider>
  );
}

export default App;