import { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc,
  orderBy,
  getDocs,
  where,
  setDoc  // Add setDoc for manual ID assignment
} from 'firebase/firestore';
import { db } from '../firebase/config';
import { isMultiVolumeWork, parseVolumeDescription } from '../utils/volumeUtils';

// Enhanced data cleaning function - avoid null values that cause Firebase issues
const cleanBookData = (bookData) => {
  const cleaned = {};
  
  // Iterate through all fields and replace undefined/null with appropriate defaults
  Object.keys(bookData).forEach(key => {
    const value = bookData[key];
    
    if (value === undefined || value === null) {
      // Set defaults based on field type - avoid null values
      if (key === 'volumeStatus') {
        cleaned[key] = {}; // Use empty object instead of null
      } else if (key === 'pages' || key === 'price' || key === 'publishYear' || key === 'volumeCount') {
        cleaned[key] = 0;
      } else if (Array.isArray(value) || key.includes('authors') || key.includes('keywords') || key.includes('subjects')) {
        cleaned[key] = [];
      } else if (typeof value === 'boolean' || key === 'isMultiVolume') {
        cleaned[key] = false;
      } else if (key === 'checkedOutBy' || key === 'dueDate' || key === 'checkoutDate') {
        // For fields that should be null when empty, use deleteField() or omit entirely
        // But for now, use empty string to avoid Firebase issues
        cleaned[key] = '';
      } else {
        cleaned[key] = ''; // Use empty string instead of null
      }
    } else {
      cleaned[key] = value;
    }
  });
  
  return cleaned;
};

// Generate a proper book ID
const generateBookId = (bookData) => {
  // Use ISBN if available
  if (bookData.isbn13) {
    return `isbn13_${bookData.isbn13.replace(/[^0-9]/g, '')}`;
  }
  if (bookData.isbn) {
    return `isbn_${bookData.isbn.replace(/[^0-9]/g, '')}`;
  }
  
  // Use title + author combination
  const titlePart = (bookData.title || 'untitled')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .substring(0, 20);
  
  const authorPart = (bookData.author || 'unknown')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
    .substring(0, 15);
  
  // Add timestamp to ensure uniqueness
  const timestamp = Date.now().toString().slice(-6);
  
  return `book_${titlePart}_${authorPart}_${timestamp}`;
};

export const useBooks = () => {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const q = query(collection(db, 'books'), orderBy('title'));
    
    const unsubscribe = onSnapshot(q, 
      (snapshot) => {
        try {
          const booksData = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          setBooks(booksData);
          setLoading(false);
          setError(null);
        } catch (err) {
          console.error('Error processing books data:', err);
          setError(err.message);
          setLoading(false);
        }
      },
      (error) => {
        console.error('Firestore onSnapshot error:', error);
        setError(error.message);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  const addBook = async (bookData) => {
    try {
      console.log('Adding book with data:', bookData);
      
      // Generate a proper ID for the book
      const bookId = generateBookId(bookData);
      console.log('Generated book ID:', bookId);
      
      // Check if this is a multi-volume work
      const volumes = parseVolumeDescription(bookData.description);
      const isMultiVolume = volumes && volumes.length > 1;
      
      // Enhanced book data with multi-volume support
      const enhancedBookData = {
        ...bookData,
        id: bookId,  // Explicitly set the ID
        status: 'available',
        checkedOutBy: '', // Use empty string instead of null
        dueDate: '', // Use empty string instead of null
        checkoutDate: '', // Use empty string instead of null
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),  // Add updated timestamp
        
        // Multi-volume specific fields - Use empty object instead of null
        isMultiVolume: isMultiVolume,
        volumeCount: isMultiVolume ? volumes.length : 1,
        volumeStatus: isMultiVolume ? {} : {}, // Always use empty object
        
        // Multi-author support
        authors: Array.isArray(bookData.authors) ? bookData.authors : 
                bookData.author ? [bookData.author] : [],
        
        // Enhanced subjects/tags support
        subjects: Array.isArray(bookData.subjects) ? bookData.subjects : [],
        
        // Backward compatibility
        author: bookData.author || (Array.isArray(bookData.authors) && bookData.authors[0]) || '',
        additionalAuthors: Array.isArray(bookData.additionalAuthors) ? bookData.additionalAuthors : [],
        subject: Array.isArray(bookData.subjects) ? bookData.subjects.join(', ') : (bookData.subject || ''),
        
        // Set default values for all fields - use empty strings instead of null
        title: bookData.title || '',
        subtitle: bookData.subtitle || '',
        isbn: bookData.isbn || '',
        isbn13: bookData.isbn13 || '',
        publisher: bookData.publisher || '',
        publishYear: parseInt(bookData.publishYear) || 0,
        publishPlace: bookData.publishPlace || '',
        edition: bookData.edition || '',
        description: bookData.description || '',
        language: bookData.language || 'English',
        format: bookData.format || 'Print',
        pages: parseInt(bookData.pages) || 0,
        genre: bookData.genre || '',
        series: bookData.series || '',
        seriesNumber: bookData.seriesNumber || '',
        callNumber: bookData.callNumber || '',
        deweyDecimal: bookData.deweyDecimal || '',
        location: bookData.location || '',
        cataloger: bookData.cataloger || '',
        catalogDate: bookData.catalogDate || new Date().toISOString().split('T')[0],
        notes: bookData.notes || '',
        acquisitionDate: bookData.acquisitionDate || '',
        condition: bookData.condition || 'Good',
        
        // Additional fields that might be missing
        lcClass: bookData.lcClass || '',
        price: parseFloat(bookData.price) || 0,
        acquisitionSource: bookData.acquisitionSource || '',
        keywords: Array.isArray(bookData.keywords) ? bookData.keywords : [],
        dimensions: bookData.dimensions || '',
        illustrations: bookData.illustrations || '',
        url: bookData.url || '',
        doi: bookData.doi || '',
        issn: bookData.issn || '',
        rights: bookData.rights || '',
        coverage: bookData.coverage || '',
        relation: bookData.relation || '',
        source: bookData.source || '',
        worldcatId: bookData.worldcatId || '',
        librarythingId: bookData.librarythingId || ''
      };

      console.log('Enhanced book data with ID:', enhancedBookData);
      
      // Clean the data before sending to Firebase
      const cleanedData = cleanBookData(enhancedBookData);
      
      console.log('Cleaned book data:', cleanedData);
      
      // Use setDoc with the generated ID instead of addDoc
      await setDoc(doc(db, 'books', bookId), cleanedData);
      console.log('Book added successfully with ID:', bookId);
      
      setError(null);
      
      // Return the book data with ID for immediate use
      return {
        id: bookId,
        ...cleanedData
      };
      
    } catch (error) {
      console.error('Error adding book:', error);
      setError(`Failed to add book: ${error.message}`);
      throw error;
    }
  };

  const updateBook = async (id, updates) => {
    try {
      if (!id || typeof id !== 'string' || id.trim() === '') {
        console.error('Invalid book ID for update:', id, typeof id);
        throw new Error(`Invalid book ID provided for update: ${id} (type: ${typeof id})`);
      }
      
      console.log('Updating book:', id, updates);
      
      // Add updated timestamp
      const updatesWithTimestamp = {
        ...updates,
        updatedAt: new Date().toISOString()
      };
      
      // Clean the update data before sending to Firebase
      const cleanedUpdates = cleanBookData(updatesWithTimestamp);
      
      await updateDoc(doc(db, 'books', id), cleanedUpdates);
      setError(null);
    } catch (error) {
      console.error('Error updating book:', error);
      setError(`Failed to update book: ${error.message}`);
      throw error;
    }
  };

  const deleteBook = async (id) => {
    try {
      if (!id || typeof id !== 'string' || id.trim() === '') {
        console.error('Invalid book ID for deletion:', id, typeof id);
        throw new Error(`Invalid book ID provided for deletion: ${id} (type: ${typeof id})`);
      }
      
      console.log('Deleting book:', id);
      await deleteDoc(doc(db, 'books', id));
      setError(null);
    } catch (error) {
      console.error('Error deleting book:', error);
      setError(`Failed to delete book: ${error.message}`);
      throw error;
    }
  };

  // Enhanced checkout for multi-volume works
  const checkoutBook = async (id, patronName, volumeNumber = null) => {
    const checkoutDate = new Date().toISOString().split('T')[0];
    const dueDate = new Date();
    dueDate.setDate(dueDate.getDate() + 14);
    
    try {
      if (!id || typeof id !== 'string') {
        throw new Error('Invalid book ID provided for checkout');
      }
      
      const book = books.find(b => b.id === id);
      if (!book) throw new Error('Book not found');
      
      console.log('Checking out book:', id, 'to:', patronName, 'volume:', volumeNumber);
      
      if (isMultiVolumeWork(book) && volumeNumber) {
        // Checkout specific volume
        const currentVolumeStatus = book.volumeStatus || {};
        const updatedVolumeStatus = {
          ...currentVolumeStatus,
          [volumeNumber]: {
            status: 'checked_out',
            checkedOutBy: patronName,
            dueDate: dueDate.toISOString().split('T')[0],
            checkoutDate: checkoutDate
          }
        };
        
        // Clean the data before updating
        const updateData = cleanBookData({
          volumeStatus: updatedVolumeStatus,
          updatedAt: new Date().toISOString()
        });
        
        await updateDoc(doc(db, 'books', id), updateData);
        
        // Create circulation record for specific volume
        const volumes = parseVolumeDescription(book.description);
        const volume = volumes.find(v => v.number === volumeNumber);
        
        // Generate circulation record ID
        const circulationId = `circ_${id}_vol${volumeNumber}_${Date.now()}`;
        
        const circulationData = cleanBookData({
          id: circulationId,
          bookId: id,
          bookTitle: `${book.title} - ${volume ? volume.title : `Volume ${volumeNumber}`}`,
          bookAuthor: book.author || (book.authors && book.authors[0]) || 'Unknown Author',
          patronName: patronName,
          checkoutDate: checkoutDate,
          dueDate: dueDate.toISOString().split('T')[0],
          status: 'checked_out',
          isOverdue: false,
          volumeNumber: volumeNumber,
          isMultiVolume: true,
          createdAt: new Date().toISOString()
        });
        
        await setDoc(doc(db, 'circulation', circulationId), circulationData);
      } else {
        // Regular single book checkout
        const updateData = cleanBookData({
          status: 'checked_out',
          checkedOutBy: patronName,
          dueDate: dueDate.toISOString().split('T')[0],
          checkoutDate: checkoutDate,
          updatedAt: new Date().toISOString()
        });
        
        await updateDoc(doc(db, 'books', id), updateData);

        // Generate circulation record ID
        const circulationId = `circ_${id}_${Date.now()}`;
        
        const circulationData = cleanBookData({
          id: circulationId,
          bookId: id,
          bookTitle: book.title || 'Unknown Title',
          bookAuthor: book.author || (book.authors && book.authors[0]) || 'Unknown Author',
          patronName: patronName,
          checkoutDate: checkoutDate,
          dueDate: dueDate.toISOString().split('T')[0],
          status: 'checked_out',
          isOverdue: false,
          volumeNumber: '', // Use empty string instead of null
          isMultiVolume: false,
          createdAt: new Date().toISOString()
        });
        
        await setDoc(doc(db, 'circulation', circulationId), circulationData);
      }
      
      setError(null);
    } catch (error) {
      console.error('Error checking out book:', error);
      setError(`Failed to checkout book: ${error.message}`);
      throw error;
    }
  };

  // Enhanced return for multi-volume works
  const returnBook = async (id, volumeNumber = null) => {
    const returnDate = new Date().toISOString().split('T')[0];
    
    try {
      if (!id || typeof id !== 'string') {
        throw new Error('Invalid book ID provided for return');
      }
      
      const book = books.find(b => b.id === id);
      if (!book) throw new Error('Book not found');
      
      console.log('Returning book:', id, 'volume:', volumeNumber);
      
      if (isMultiVolumeWork(book) && volumeNumber) {
        // Return specific volume
        const currentVolumeStatus = book.volumeStatus || {};
        const updatedVolumeStatus = {
          ...currentVolumeStatus,
          [volumeNumber]: {
            status: 'available',
            checkedOutBy: '',
            dueDate: '',
            checkoutDate: ''
          }
        };
        
        // Clean the data before updating
        const updateData = cleanBookData({
          volumeStatus: updatedVolumeStatus,
          updatedAt: new Date().toISOString()
        });
        
        await updateDoc(doc(db, 'books', id), updateData);
        
        // Update circulation record for specific volume
        const circulationQuery = query(
          collection(db, 'circulation'),
          where('bookId', '==', id),
          where('volumeNumber', '==', volumeNumber),
          where('status', '==', 'checked_out')
        );
        
        const circulationSnapshot = await getDocs(circulationQuery);
        if (!circulationSnapshot.empty) {
          const circulationDoc = circulationSnapshot.docs[0];
          const circulationData = circulationDoc.data();
          
          const dueDate = new Date(circulationData.dueDate);
          const returnDateObj = new Date(returnDate);
          const isOverdue = returnDateObj > dueDate;
          const overdueDays = isOverdue ? Math.ceil((returnDateObj - dueDate) / (1000 * 60 * 60 * 24)) : 0;
          
          const updateData = cleanBookData({
            returnDate: returnDate,
            status: 'returned',
            isOverdue: isOverdue,
            overdueDays: overdueDays,
            fineAmount: overdueDays * 0.50,
            updatedAt: new Date().toISOString()
          });
          
          await updateDoc(doc(db, 'circulation', circulationDoc.id), updateData);
        }
      } else {
        // Regular single book return
        const updateData = cleanBookData({
          status: 'available',
          checkedOutBy: '',
          dueDate: '',
          checkoutDate: '',
          updatedAt: new Date().toISOString()
        });
        
        await updateDoc(doc(db, 'books', id), updateData);

        const circulationQuery = query(
          collection(db, 'circulation'),
          where('bookId', '==', id),
          where('status', '==', 'checked_out')
        );
        
        const circulationSnapshot = await getDocs(circulationQuery);
        if (!circulationSnapshot.empty) {
          const circulationDoc = circulationSnapshot.docs[0];
          const circulationData = circulationDoc.data();
          
          const dueDate = new Date(circulationData.dueDate);
          const returnDateObj = new Date(returnDate);
          const isOverdue = returnDateObj > dueDate;
          const overdueDays = isOverdue ? Math.ceil((returnDateObj - dueDate) / (1000 * 60 * 60 * 24)) : 0;
          
          const updateData = cleanBookData({
            returnDate: returnDate,
            status: 'returned',
            isOverdue: isOverdue,
            overdueDays: overdueDays,
            fineAmount: overdueDays * 0.50,
            updatedAt: new Date().toISOString()
          });
          
          await updateDoc(doc(db, 'circulation', circulationDoc.id), updateData);
        }
      }
      
      setError(null);
    } catch (error) {
      console.error('Error returning book:', error);
      setError(`Failed to return book: ${error.message}`);
      throw error;
    }
  };

  // Function to check if a book ID already exists
  const checkBookExists = async (potentialId) => {
    try {
      const bookDoc = await getDocs(query(
        collection(db, 'books'),
        where('id', '==', potentialId)
      ));
      return !bookDoc.empty;
    } catch (error) {
      console.error('Error checking if book exists:', error);
      return false;
    }
  };

  return {
    books,
    loading,
    error,
    addBook,
    updateBook,
    deleteBook,
    checkoutBook,
    returnBook,
    checkBookExists
  };
};