import React, { useState } from 'react';
import { Edit2, Trash2, CheckCircle, XCircle, Calendar, Users, Tag, Book, ChevronDown, ChevronUp } from 'lucide-react';
import { isMultiVolumeWork, parseVolumeDescription, getAllVolumeStatuses } from '../utils/volumeUtils';
import { useLanguage } from '../contexts/LanguageContext';
import { translateLanguage, translateFormat, translateCondition } from '../utils/languageTranslations';

const BookCard = ({ book, patrons = [], onEdit, onDelete, onCheckout, onReturn, isPublic = false }) => {
  const { language } = useLanguage();
  const [showVolumeDetails, setShowVolumeDetails] = useState(false);
  
  // Early return if book is invalid
  if (!book) {
    console.error('BookCard received invalid book:', book);
    return null;
  }
  
  // Helper functions
  const getAllAuthors = () => {
    if (book.authors && Array.isArray(book.authors)) {
      return book.authors;
    } else if (book.author) {
      const authors = [book.author];
      if (book.additionalAuthors && Array.isArray(book.additionalAuthors)) {
        authors.push(...book.additionalAuthors);
      }
      return authors;
    }
    return [];
  };

  const getSubjects = () => {
    if (book.subjects && Array.isArray(book.subjects)) {
      return book.subjects;
    } else if (book.subject) {
      return book.subject.split(',').map(s => s.trim()).filter(s => s);
    }
    return [];
  };

  const authors = getAllAuthors();
  const subjects = getSubjects();
  const primaryAuthor = authors[0] || (language === 'uk' ? 'Невідомий автор' : 'Unknown Author');
  const additionalAuthors = authors.slice(1);
  const isMultiVolume = isMultiVolumeWork(book);
  
  // Multi-volume specific data
  let volumes = [];
  let volumeStatuses = [];
  let availableVolumes = 0;
  let checkedOutVolumes = 0;
  
  if (isMultiVolume) {
    volumes = parseVolumeDescription(book.description) || [];
    volumeStatuses = getAllVolumeStatuses(book);
    availableVolumes = volumeStatuses.filter(v => v.status === 'available').length;
    checkedOutVolumes = volumeStatuses.filter(v => v.status === 'checked_out').length;
  }

  const getOverallStatus = () => {
    if (!isMultiVolume) {
      return book.status || 'available';
    }
    
    if (availableVolumes === 0) return 'all_checked_out';
    if (checkedOutVolumes === 0) return 'available';
    return 'partially_checked_out';
  };

  const overallStatus = getOverallStatus();

  // Truncate long descriptions for multi-volume works
  const getTruncatedDescription = (description, maxLength = 200) => {
    if (!description) return '';
    if (description.length <= maxLength) return description;
    return description.substring(0, maxLength) + '...';
  };

  // Translate book language and format
  const translatedLanguage = translateLanguage(book.language, language);
  const translatedFormat = translateFormat(book.format, language);
  const translatedCondition = translateCondition(book.condition, language);

  // Safe handlers for edit and delete
  const handleEdit = () => {
    if (!book.id) {
      console.error('Cannot edit book: missing ID', book);
      return;
    }
    onEdit && onEdit(book);
  };

  const handleDelete = () => {
    if (!book.id) {
      console.error('Cannot delete book: missing ID', book);
      alert(language === 'uk' 
        ? 'Помилка: Неможливо видалити книгу без ID' 
        : 'Error: Cannot delete book without ID'
      );
      return;
    }
    
    // Add confirmation dialog
    const confirmMessage = language === 'uk' 
      ? `Ви впевнені, що хочете видалити "${book.title}"?`
      : `Are you sure you want to delete "${book.title}"?`;
    
    if (window.confirm(confirmMessage)) {
      onDelete && onDelete(book.id);
    }
  };

  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-lg shadow-md hover:shadow-lg transition-all duration-200 p-6 border border-white/20">
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">
            {book.title || (language === 'uk' ? 'Без назви' : 'Untitled')}
            {book.subtitle && <span className="text-gray-600">: {book.subtitle}</span>}
            {isMultiVolume && (
              <span className="ml-2 inline-flex items-center px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded-full">
                <Book className="h-3 w-3 mr-1" />
                {language === 'uk' 
                  ? `${volumes.length} томів` 
                  : `${volumes.length} volumes`
                }
              </span>
            )}
          </h3>
          
          {/* Primary Author */}
          <p className="text-gray-600">
            {language === 'uk' ? 'автор' : 'by'} {primaryAuthor}
          </p>
          
          {/* Additional Authors */}
          {additionalAuthors.length > 0 && (
            <div className="text-sm text-gray-500 mt-1">
              <div className="flex items-center">
                <Users className="h-3 w-3 mr-1" />
                <span>
                  {additionalAuthors.length === 1 
                    ? (language === 'uk' ? 'Співавтор: ' : 'Co-author: ')
                    : (language === 'uk' ? 'Співавтори: ' : 'Co-authors: ')
                  }
                  {additionalAuthors.join(', ')}
                </span>
              </div>
            </div>
          )}
          
          <div className="text-sm text-gray-500 space-y-1 mt-2">
            <p>
              {language === 'uk' ? 'Опубліковано: ' : 'Published: '}
              {book.publishYear || (language === 'uk' ? 'Невідомо' : 'Unknown')} 
              {book.publisher && ` ${language === 'uk' ? 'видавництвом' : 'by'} ${book.publisher}`}
            </p>
            {book.edition && (
              <p>
                {language === 'uk' ? 'Видання: ' : 'Edition: '}{book.edition}
              </p>
            )}
            {!isMultiVolume && book.pages && (
              <p>
                {language === 'uk' ? 'Сторінки: ' : 'Pages: '}{book.pages}
              </p>
            )}
            {isMultiVolume && (
              <p>
                {language === 'uk' 
                  ? `Формат: Багатотомне видання (${volumes.length} томів)`
                  : `Format: Multi-volume work (${volumes.length} volumes)`
                }
              </p>
            )}
            <p>
              {language === 'uk' ? 'Жанр: ' : 'Genre: '}
              {book.genre || (language === 'uk' ? 'Не вказано' : 'Not specified')}
            </p>
            {book.series && (
              <p>
                {language === 'uk' ? 'Серія: ' : 'Series: '}{book.series}
              </p>
            )}
            {book.language && book.language !== 'English' && (
              <p>
                {language === 'uk' ? 'Мова: ' : 'Language: '}{translatedLanguage}
              </p>
            )}
            {book.format && book.format !== 'Print' && (
              <p>
                {language === 'uk' ? 'Формат: ' : 'Format: '}{translatedFormat}
              </p>
            )}
            {book.condition && (
              <p>
                {language === 'uk' ? 'Стан: ' : 'Condition: '}{translatedCondition}
              </p>
            )}
          </div>

          {/* Subject Tags */}
          {subjects.length > 0 && (
            <div className="mt-3">
              <div className="flex flex-wrap gap-1">
                {subjects.slice(0, 3).map((subject, index) => (
                  <span
                    key={index}
                    className="inline-flex items-center px-2 py-1 bg-red-100/80 text-red-800 text-xs rounded-full backdrop-blur-sm"
                  >
                    <Tag className="h-2 w-2 mr-1" />
                    {subject}
                  </span>
                ))}
                {subjects.length > 3 && (
                  <span className="text-xs text-gray-500">
                    +{subjects.length - 3} {language === 'uk' ? 'ще' : 'more'}
                  </span>
                )}
              </div>
            </div>
          )}
          
          {/* Compact multi-volume summary */}
          {isMultiVolume && (
            <div className="mt-3 p-3 bg-blue-50/80 backdrop-blur-sm rounded text-sm">
              <div className="flex justify-between items-center mb-2">
                <p className="text-blue-800 font-medium">
                  {language === 'uk' ? 'Багатотомне видання' : 'Multi-volume work'}
                </p>
                <button
                  onClick={() => setShowVolumeDetails(!showVolumeDetails)}
                  className="text-blue-600 hover:text-blue-800 text-xs flex items-center"
                >
                  {showVolumeDetails ? (
                    <>
                      <ChevronUp className="h-3 w-3 mr-1" />
                      {language === 'uk' ? 'Приховати деталі' : 'Hide details'}
                    </>
                  ) : (
                    <>
                      <ChevronDown className="h-3 w-3 mr-1" />
                      {language === 'uk' ? 'Показати томи' : 'Show volumes'}
                    </>
                  )}
                </button>
              </div>
              
              <p className="text-blue-700 mb-2">
                {language === 'uk' 
                  ? `${availableVolumes} з ${volumes.length} томів доступно`
                  : `${availableVolumes} of ${volumes.length} volumes available`
                }
                {checkedOutVolumes > 0 && (
                  language === 'uk' 
                    ? ` • ${checkedOutVolumes} видано`
                    : ` • ${checkedOutVolumes} checked out`
                )}
              </p>

              {!showVolumeDetails && (
                <div className="text-xs text-blue-600">
                  <p>{getTruncatedDescription(book.description, 150)}</p>
                  {book.description && book.description.length > 150 && (
                    <button
                      onClick={() => setShowVolumeDetails(true)}
                      className="text-blue-600 hover:text-blue-800 mt-1"
                    >
                      {language === 'uk' 
                        ? 'Натисніть, щоб побачити всі томи'
                        : 'Click to see all volumes'
                      }
                    </button>
                  )}
                </div>
              )}

              {/* Detailed Volume List - Only when expanded */}
              {showVolumeDetails && (
                <div className="space-y-2 max-h-40 overflow-y-auto border-t border-blue-200 pt-2 mt-2">
                  {volumeStatuses.slice(0, 8).map((volume, index) => (
                    <div key={volume.number} className="flex justify-between items-start text-xs">
                      <div className="flex-1 mr-2">
                        <p className="font-medium text-gray-900">
                          {language === 'uk' ? 'Том' : 'Vol.'} {volume.number}
                        </p>
                        <p className="text-gray-600 truncate" title={volume.title}>
                          {volume.title.length > 40 ? volume.title.substring(0, 40) + '...' : volume.title}
                        </p>
                      </div>
                      <div className="text-right flex-shrink-0">
                        {volume.status === 'available' ? (
                          <span className="inline-flex items-center px-1.5 py-0.5 bg-green-100 text-green-800 text-xs rounded">
                            <CheckCircle className="h-2 w-2 mr-1" />
                            {language === 'uk' ? 'Доступно' : 'Available'}
                          </span>
                        ) : (
                          <div>
                            <span className="inline-flex items-center px-1.5 py-0.5 bg-red-100 text-red-800 text-xs rounded mb-1">
                              <XCircle className="h-2 w-2 mr-1" />
                              {language === 'uk' ? 'Видано' : 'Out'}
                            </span>
                            <p className="text-xs text-gray-600">
                              {language === 'uk' ? 'Кому: ' : 'To: '}{volume.checkedOutBy}
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                  {volumeStatuses.length > 8 && (
                    <p className="text-xs text-blue-600 text-center py-2">
                      {language === 'uk' 
                        ? `... та ще ${volumeStatuses.length - 8} томів`
                        : `... and ${volumeStatuses.length - 8} more volumes`
                      }
                    </p>
                  )}
                </div>
              )}
            </div>
          )}
          
          {/* Regular description for single volumes - keep it short */}
          {!isMultiVolume && book.description && (
            <div className="mt-3 p-2 bg-gray-50/80 backdrop-blur-sm rounded text-sm">
              <p className="text-gray-700">
                {getTruncatedDescription(book.description, 120)}
              </p>
            </div>
          )}
          
          {/* Library cataloging info - condensed */}
          {(book.callNumber || book.deweyDecimal || book.location) && (
            <div className="mt-3 text-xs text-gray-500 border-t pt-2">
              {book.callNumber && (
                <span>
                  {language === 'uk' ? 'Шифр' : 'Call #'}: {book.callNumber} • 
                </span>
              )}
              {book.deweyDecimal && <span>Dewey: {book.deweyDecimal} • </span>}
              {book.location && (
                <span>
                  {language === 'uk' ? 'Розташування: ' : 'Location: '}{book.location}
                </span>
              )}
            </div>
          )}
          
          {/* ISBNs - condensed */}
          {(book.isbn || book.isbn13) && (
            <div className="mt-2 text-xs text-gray-500">
              {book.isbn && <span>ISBN: {book.isbn} </span>}
              {book.isbn13 && <span>ISBN-13: {book.isbn13}</span>}
            </div>
          )}

          {/* Debug info - remove in production */}
          {!book.id && (
            <div className="mt-2 p-2 bg-yellow-100 border border-yellow-400 text-yellow-700 text-xs rounded">
              <strong>Warning:</strong> This book has no ID and cannot be edited or deleted.
            </div>
          )}
        </div>
        
        {/* Admin buttons - only show if book has valid ID */}
        {!isPublic && book.id && (
          <div className="flex space-x-1 flex-shrink-0 ml-2">
            <button
              onClick={handleEdit}
              className="p-1 text-gray-400 hover:text-red-600 transition-colors"
              title={language === 'uk' ? 'Редагувати книгу' : 'Edit book'}
            >
              <Edit2 className="h-4 w-4" />
            </button>
            <button
              onClick={handleDelete}
              className="p-1 text-gray-400 hover:text-red-600 transition-colors"
              title={language === 'uk' ? 'Видалити книгу' : 'Delete book'}
            >
              <Trash2 className="h-4 w-4" />
            </button>
          </div>
        )}
      </div>

      {/* Status section with multi-volume support */}
      <div className="border-t pt-4">
        {isMultiVolume ? (
          <div>
            <div className="flex items-center mb-2">
              {overallStatus === 'available' ? (
                <>
                  <CheckCircle className="h-4 w-4 text-green-500 mr-2" />
                  <span className="text-green-600 font-medium">
                    {language === 'uk' ? 'Всі томи доступні' : 'All volumes available'}
                  </span>
                </>
              ) : overallStatus === 'all_checked_out' ? (
                <>
                  <XCircle className="h-4 w-4 text-red-500 mr-2" />
                  <span className="text-red-600 font-medium">
                    {language === 'uk' ? 'Всі томи видано' : 'All volumes checked out'}
                  </span>
                </>
              ) : (
                <>
                  <Calendar className="h-4 w-4 text-yellow-500 mr-2" />
                  <span className="text-yellow-600 font-medium">
                    {language === 'uk' 
                      ? `${availableVolumes} доступно, ${checkedOutVolumes} видано`
                      : `${availableVolumes} available, ${checkedOutVolumes} checked out`
                    }
                  </span>
                </>
              )}
            </div>
            
            {!isPublic && patrons && availableVolumes > 0 && book.id && (
              <div className="space-y-2">
                <select
                  onChange={(e) => {
                    const [patronName, volumeNumber] = e.target.value.split('|');
                    if (patronName && volumeNumber) {
                      onCheckout && onCheckout(book.id, patronName, parseInt(volumeNumber));
                      e.target.value = '';
                    }
                  }}
                  className="w-full border border-gray-300 rounded-md px-3 py-1 text-sm bg-white/90 backdrop-blur-sm"
                  defaultValue=""
                >
                  <option value="">
                    {language === 'uk' ? 'Видати том...' : 'Checkout volume to...'}
                  </option>
                  {patrons.map(patron => 
                    volumeStatuses
                      .filter(vol => vol.status === 'available')
                      .slice(0, 10) // Limit dropdown options
                      .map(vol => (
                        <option key={`${patron.id}-${vol.number}`} value={`${patron.name}|${vol.number}`}>
                          {patron.name} - {language === 'uk' ? 'Том' : 'Vol.'} {vol.number}
                        </option>
                      ))
                  )}
                </select>
              </div>
            )}
            
            {!isPublic && checkedOutVolumes > 0 && book.id && (
              <div className="mt-2 space-y-1">
                {volumeStatuses
                  .filter(vol => vol.status === 'checked_out')
                  .slice(0, 3) // Limit return buttons shown
                  .map(vol => (
                    <button
                      key={vol.number}
                      onClick={() => onReturn && onReturn(book.id, vol.number)}
                      className="w-full bg-green-600 text-white py-1 px-3 rounded-md text-sm hover:bg-green-700 transition-colors"
                    >
                      {language === 'uk' 
                        ? `Повернути том ${vol.number} від ${vol.checkedOutBy}`
                        : `Return Vol. ${vol.number} from ${vol.checkedOutBy}`
                      }
                    </button>
                  ))}
                {checkedOutVolumes > 3 && (
                  <p className="text-xs text-gray-500 text-center">
                    +{checkedOutVolumes - 3} {language === 'uk' ? 'ще томів видано' : 'more volumes checked out'}
                  </p>
                )}
              </div>
            )}
          </div>
        ) : (
          // Regular single book status
          <div>
            {book.status === 'available' ? (
              <div>
                <div className="flex items-center mb-2">
                  <CheckCircle className="h-4 w-4 text-green-500 mr-2" />
                  <span className="text-green-600 font-medium">
                    {language === 'uk' ? 'Доступна' : 'Available'}
                  </span>
                </div>
                {!isPublic && patrons && book.id && (
                  <select
                    onChange={(e) => e.target.value && onCheckout && onCheckout(book.id, e.target.value)}
                    className="w-full border border-gray-300 rounded-md px-3 py-1 text-sm bg-white/90 backdrop-blur-sm"
                    defaultValue=""
                  >
                    <option value="">
                      {language === 'uk' ? 'Видати кому...' : 'Checkout to...'}
                    </option>
                    {patrons.map(patron => (
                      <option key={patron.id} value={patron.name}>{patron.name}</option>
                    ))}
                  </select>
                )}
              </div>
            ) : (
              <div>
                <div className="flex items-center mb-2">
                  <XCircle className="h-4 w-4 text-red-500 mr-2" />
                  <span className="text-red-600 font-medium">
                    {language === 'uk' ? 'Видана' : 'Checked Out'}
                  </span>
                </div>
                {!isPublic && (
                  <>
                    <p className="text-sm text-gray-600 mb-2">
                      {language === 'uk' ? 'Кому: ' : 'By: '}{book.checkedOutBy}
                    </p>
                    <p className="text-sm text-gray-600 mb-3 flex items-center">
                      <Calendar className="h-3 w-3 mr-1" />
                      {language === 'uk' ? 'Повернути до: ' : 'Due: '}{book.dueDate}
                    </p>
                    {book.id && (
                      <button
                        onClick={() => onReturn && onReturn(book.id)}
                        className="w-full bg-green-600 text-white py-1 px-3 rounded-md text-sm hover:bg-green-700 transition-colors"
                      >
                        {language === 'uk' ? 'Повернути книгу' : 'Return Book'}
                      </button>
                    )}
                  </>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default BookCard;