import React, { useState } from 'react';
import { X, Book, Calendar, Globe, Tag, Users, Share2, Copy, Instagram } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

const BookDetailModal = ({ book, onClose }) => {
  const { language } = useLanguage();
  const [showShareMenu, setShowShareMenu] = useState(false);

  if (!book) return null;

  // Helper functions
  const getAllAuthors = () => {
    if (book.authors && Array.isArray(book.authors)) {
      return book.authors;
    } else if (book.author) {
      const authors = [book.author];
      if (book.additionalAuthors && Array.isArray(book.additionalAuthors)) {
        authors.push(...book.additionalAuthors);
      }
      return authors;
    }
    return [];
  };

  const getSubjects = () => {
    if (book.subjects && Array.isArray(book.subjects)) {
      return book.subjects;
    } else if (book.subject) {
      return book.subject.split(',').map(s => s.trim()).filter(s => s);
    }
    return [];
  };

  const authors = getAllAuthors();
  const subjects = getSubjects();

  // Share functionality
  const getShareText = () => {
    const title = `${book.title}${book.subtitle ? ': ' + book.subtitle : ''}`;
    const authorText = authors.length > 0 ? ` ${language === 'uk' ? 'від' : 'by'} ${authors.join(', ')}` : '';
    const publisherText = book.publisher ? ` (${book.publisher}${book.publishYear ? ', ' + book.publishYear : ''})` : '';
    
    return `📚 ${title}${authorText}${publisherText}

${book.description ? book.description.substring(0, 200) + (book.description.length > 200 ? '...' : '') : ''}

${subjects.length > 0 ? `🏷️ ${subjects.slice(0, 3).join(', ')}${subjects.length > 3 ? '...' : ''}` : ''}

${language === 'uk' ? '📖 Доступно в бібліотеці' : '📖 Available in library'}`;
  };

  const shareToFacebook = () => {
    const shareText = getShareText();
    // Facebook sharing with proper parameters
    const url = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}&t=${encodeURIComponent(book.title)}`;
    
    // Also copy the text to clipboard so users can paste it
    navigator.clipboard.writeText(shareText).catch(() => {
      console.log('Could not copy to clipboard');
    });
    
    window.open(url, '_blank', 'width=600,height=400,scrollbars=yes,resizable=yes');
    setShowShareMenu(false);
  };

  const shareToThreads = () => {
    const shareText = getShareText();
    const url = `https://threads.net/intent/post?text=${encodeURIComponent(shareText + '\n\n' + window.location.href)}`;
    window.open(url, '_blank', 'width=600,height=400');
    setShowShareMenu(false);
  };

  const shareToInstagramStories = () => {
    // Instagram Stories sharing requires the Instagram app
    const shareText = getShareText();
    
    // Copy to clipboard and show instructions
    navigator.clipboard.writeText(shareText);
    
    alert(language === 'uk' ? 
      'Текст скопійовано! Відкрийте Instagram, створіть Stories, і вставте текст. Або поділіться посиланням: ' + window.location.href :
      'Text copied! Open Instagram, create a Story, and paste the text. Or share this link: ' + window.location.href
    );
    setShowShareMenu(false);
  };

  const shareBook = async () => {
    const shareData = {
      title: `${book.title} - ${language === 'uk' ? 'Бібліотека' : 'Library'}`,
      text: getShareText(),
      url: window.location.href
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
        setShowShareMenu(false);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      // Show custom share menu instead of fallback
      setShowShareMenu(!showShareMenu);
    }
  };



  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white/95 backdrop-blur-sm rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-white/20">
        {/* Header */}
        <div className="p-6 border-b border-gray-200/50 bg-gradient-to-r from-red-50/80 to-pink-50/80">
          <div className="flex justify-between items-start">
            <div className="flex items-center">
              <Book className="h-8 w-8 text-red-600 mr-3" />
              <div>
                <h2 className="text-2xl font-bold text-gray-900">
                  {book.title}
                </h2>
                {book.subtitle && (
                  <p className="text-lg text-gray-600 mt-1">{book.subtitle}</p>
                )}
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <div className="relative">
                <button
                  onClick={shareBook}
                  className="p-2 text-gray-500 hover:text-red-600 transition-colors rounded-full hover:bg-white/50"
                  title={language === 'uk' ? 'Поділитися' : 'Share'}
                >
                  <Share2 className="h-5 w-5" />
                </button>
                
                {/* Custom Share Menu */}
                {showShareMenu && (
                  <div className="absolute right-0 top-12 bg-white backdrop-blur-sm border border-gray-200 rounded-lg shadow-xl p-3 z-50 min-w-52">
                    <div className="space-y-2">
                      <button
                        onClick={shareToFacebook}
                        className="flex items-center w-full px-3 py-2 text-left hover:bg-blue-50 rounded-md transition-colors"
                      >
                        <div className="w-6 h-6 bg-blue-600 rounded mr-3 flex items-center justify-center">
                          <span className="text-white text-sm font-bold">f</span>
                        </div>
                        <span className="text-gray-700 font-medium">Facebook</span>
                      </button>
                      
                      <button
                        onClick={shareToThreads}
                        className="flex items-center w-full px-3 py-2 text-left hover:bg-gray-50 rounded-md transition-colors"
                      >
                        <div className="w-6 h-6 bg-black rounded mr-3 flex items-center justify-center">
                          <span className="text-white text-sm font-bold">@</span>
                        </div>
                        <span className="text-gray-700 font-medium">Threads</span>
                      </button>
                      
                      <button
                        onClick={shareToInstagramStories}
                        className="flex items-center w-full px-3 py-2 text-left hover:bg-pink-50 rounded-md transition-colors"
                      >
                        <div className="w-6 h-6 bg-gradient-to-br from-purple-500 to-pink-500 rounded mr-3 flex items-center justify-center">
                          <Instagram className="h-3 w-3 text-white" />
                        </div>
                        <span className="text-gray-700 font-medium">Instagram Stories</span>
                      </button>
                      
                      <hr className="my-2 border-gray-200" />
                      
                      <button
                        onClick={() => {
                          navigator.clipboard.writeText(getShareText() + '\n\n' + window.location.href);
                          alert(language === 'uk' ? 'Посилання скопійовано!' : 'Link copied!');
                          setShowShareMenu(false);
                        }}
                        className="flex items-center w-full px-3 py-2 text-left hover:bg-gray-50 rounded-md transition-colors"
                      >
                        <Copy className="h-5 w-5 text-gray-500 mr-3" />
                        <span className="text-gray-700 font-medium">
                          {language === 'uk' ? 'Копіювати посилання' : 'Copy link'}
                        </span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
              <button
                onClick={onClose}
                className="p-2 text-gray-500 hover:text-red-600 transition-colors rounded-full hover:bg-white/50"
                title={language === 'uk' ? 'Закрити' : 'Close'}
              >
                <X className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="p-6 space-y-6">
          {/* Authors */}
          <div className="flex items-start space-x-3">
            <Users className="h-5 w-5 text-red-600 mt-1 flex-shrink-0" />
            <div>
              <h3 className="font-semibold text-gray-900 mb-2">
                {language === 'uk' ? 
                  (authors.length > 1 ? 'Автори' : 'Автор') : 
                  (authors.length > 1 ? 'Authors' : 'Author')
                }
              </h3>
              <div className="space-y-1">
                {authors.map((author, index) => (
                  <p key={index} className="text-gray-700">
                    {author} {index === 0 && authors.length > 1 && (
                      <span className="text-sm text-gray-500">
                        ({language === 'uk' ? 'основний автор' : 'primary author'})
                      </span>
                    )}
                  </p>
                ))}
              </div>
            </div>
          </div>

          {/* Publication Info */}
          <div className="flex items-start space-x-3">
            <Calendar className="h-5 w-5 text-red-600 mt-1 flex-shrink-0" />
            <div>
              <h3 className="font-semibold text-gray-900 mb-2">
                {language === 'uk' ? 'Публікація' : 'Publication'}
              </h3>
              <div className="space-y-1 text-gray-700">
                {book.publisher && (
                  <p><span className="font-medium">{language === 'uk' ? 'Видавець:' : 'Publisher:'}</span> {book.publisher}</p>
                )}
                {book.publishYear && (
                  <p><span className="font-medium">{language === 'uk' ? 'Рік:' : 'Year:'}</span> {book.publishYear}</p>
                )}
                {book.publishPlace && (
                  <p><span className="font-medium">{language === 'uk' ? 'Місце:' : 'Place:'}</span> {book.publishPlace}</p>
                )}
                {book.edition && (
                  <p><span className="font-medium">{language === 'uk' ? 'Видання:' : 'Edition:'}</span> {book.edition}</p>
                )}
              </div>
            </div>
          </div>

          {/* Description */}
          {book.description && (
            <div className="bg-gray-50/80 backdrop-blur-sm rounded-lg p-4">
              <h3 className="font-semibold text-gray-900 mb-2">
                {language === 'uk' ? 'Опис' : 'Description'}
              </h3>
              <p className="text-gray-700 leading-relaxed">{book.description}</p>
            </div>
          )}

          {/* Subjects/Keywords */}
          {subjects.length > 0 && (
            <div className="flex items-start space-x-3">
              <Tag className="h-5 w-5 text-red-600 mt-1 flex-shrink-0" />
              <div>
                <h3 className="font-semibold text-gray-900 mb-2">
                  {language === 'uk' ? 'Теми' : 'Subjects'}
                </h3>
                <div className="flex flex-wrap gap-2">
                  {subjects.map((subject, index) => (
                    <span
                      key={index}
                      className="inline-flex items-center px-3 py-1 bg-red-100/80 text-red-800 text-sm rounded-full backdrop-blur-sm"
                    >
                      {subject}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Physical Details */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-blue-50/50 rounded-lg p-4">
              <h3 className="font-semibold text-gray-900 mb-3">
                {language === 'uk' ? 'Фізичні характеристики' : 'Physical Details'}
              </h3>
              <div className="space-y-2 text-sm">
                {book.pages && (
                  <p><span className="font-medium">{language === 'uk' ? 'Сторінки:' : 'Pages:'}</span> {book.pages}</p>
                )}
                {book.dimensions && (
                  <p><span className="font-medium">{language === 'uk' ? 'Розміри:' : 'Dimensions:'}</span> {book.dimensions}</p>
                )}
                {book.format && (
                  <p><span className="font-medium">{language === 'uk' ? 'Формат:' : 'Format:'}</span> {book.format}</p>
                )}
                {book.language && (
                  <p><span className="font-medium">{language === 'uk' ? 'Мова:' : 'Language:'}</span> {book.language}</p>
                )}
              </div>
            </div>

            <div className="bg-green-50/50 rounded-lg p-4">
              <h3 className="font-semibold text-gray-900 mb-3">
                {language === 'uk' ? 'Ідентифікатори' : 'Identifiers'}
              </h3>
              <div className="space-y-2 text-sm">
                {book.isbn && (
                  <p><span className="font-medium">ISBN:</span> {book.isbn}</p>
                )}
                {book.isbn13 && (
                  <p><span className="font-medium">ISBN-13:</span> {book.isbn13}</p>
                )}
                {book.issn && (
                  <p><span className="font-medium">ISSN:</span> {book.issn}</p>
                )}
                {book.doi && (
                  <p><span className="font-medium">DOI:</span> {book.doi}</p>
                )}
              </div>
            </div>
          </div>

          {/* Series & Genre */}
          {(book.series || book.genre) && (
            <div className="flex items-start space-x-3">
              <Globe className="h-5 w-5 text-red-600 mt-1 flex-shrink-0" />
              <div className="space-y-2">
                {book.genre && (
                  <p><span className="font-medium">{language === 'uk' ? 'Жанр:' : 'Genre:'}</span> {book.genre}</p>
                )}
                {book.series && (
                  <p><span className="font-medium">{language === 'uk' ? 'Серія:' : 'Series:'}</span> {book.series}</p>
                )}
              </div>
            </div>
          )}

          {/* Library Info */}
          {(book.callNumber || book.deweyDecimal || book.location) && (
            <div className="bg-yellow-50/50 rounded-lg p-4">
              <h3 className="font-semibold text-gray-900 mb-3">
                {language === 'uk' ? 'Бібліотечна інформація' : 'Library Information'}
              </h3>
              <div className="space-y-2 text-sm">
                {book.callNumber && (
                  <p><span className="font-medium">{language === 'uk' ? 'Шифр:' : 'Call Number:'}</span> {book.callNumber}</p>
                )}
                {book.deweyDecimal && (
                  <p><span className="font-medium">Dewey:</span> {book.deweyDecimal}</p>
                )}
                {book.location && (
                  <p><span className="font-medium">{language === 'uk' ? 'Розташування:' : 'Location:'}</span> {book.location}</p>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-200/50 bg-gray-50/50">
          <div className="flex justify-between items-center">
            <div className="text-sm text-gray-500">
              {language === 'uk' ? 
                'Натисніть кнопку "Поділитися" щоб поділитися цією книгою' :
                'Click "Share" button to share this book'
              }
            </div>
            <button
              onClick={onClose}
              className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
            >
              {language === 'uk' ? 'Закрити' : 'Close'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BookDetailModal;