// src/utils/volumeUtils.js
export const parseVolumeDescription = (description) => {
  if (!description) return null;
  
  // Look for volume patterns like "т. 1.", "Vol. 1:", "Volume 1", etc.
  const volumePatterns = [
    /т\.\s*(\d+)\.\s*([^\n\r]+)/gi,  // Ukrainian: "т. 1. Title"
    /vol\.\s*(\d+)[:.]?\s*([^\n\r]+)/gi,  // English: "Vol. 1: Title"
    /volume\s*(\d+)[:.]?\s*([^\n\r]+)/gi  // English: "Volume 1: Title"
  ];
  
  const volumes = [];
  
  for (const pattern of volumePatterns) {
    let match;
    while ((match = pattern.exec(description)) !== null) {
      volumes.push({
        number: parseInt(match[1]),
        title: match[2].trim(),
        fullText: match[0].trim()
      });
    }
  }
  
  // Sort by volume number
  return volumes.length > 0 ? volumes.sort((a, b) => a.number - b.number) : null;
};

export const isMultiVolumeWork = (book) => {
  if (!book) return false;
  
  // Check if book is marked as multi-volume
  if (book.isMultiVolume === true) return true;
  
  // Check if description contains volume information
  const volumes = parseVolumeDescription(book.description);
  return volumes && volumes.length > 1;
};

export const getVolumeStatus = (book, volumeNumber) => {
  if (!book.volumeStatus || !book.volumeStatus[volumeNumber]) {
    return {
      status: 'available',
      checkedOutBy: null,
      dueDate: null,
      checkoutDate: null
    };
  }
  return book.volumeStatus[volumeNumber];
};

export const getAllVolumeStatuses = (book) => {
  const volumes = parseVolumeDescription(book.description);
  if (!volumes) return [];
  
  return volumes.map(volume => ({
    ...volume,
    ...getVolumeStatus(book, volume.number)
  }));
};