import React, { useState } from 'react';
import { User, Lock, Mail, Eye, EyeOff, X, AlertCircle, CheckCircle } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';
import { usePatronAuth } from '../contexts/PatronAuthContext';

const PatronLogin = ({ onClose, onLoginSuccess }) => {
  const { language } = useLanguage();
  const { login, sendPasswordReset, isLoading } = usePatronAuth();
  const [formData, setFormData] = useState({
    identifier: '', // email or card number
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [resetSuccess, setResetSuccess] = useState(false);

  const handleInputChange = (e) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
    if (error) setError(''); // Clear error when user starts typing
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!formData.identifier || !formData.password) {
      setError(language === 'uk' ? 
        'Будь ласка, заповніть всі поля' : 
        'Please fill in all fields'
      );
      return;
    }

    const result = await login(formData.identifier, formData.password);
    
    if (result.success) {
      onLoginSuccess(result.patron);
    } else {
      setError(result.error);
    }
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    setError('');

    if (!resetEmail) {
      setError(language === 'uk' ? 
        'Будь ласка, введіть email адресу' : 
        'Please enter your email address'
      );
      return;
    }

    const result = await sendPasswordReset(resetEmail);
    
    if (result.success) {
      setResetSuccess(true);
    } else {
      setError(result.error);
    }
  };

  if (resetSuccess) {
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
        <div className="bg-white rounded-lg max-w-md w-full p-6">
          <div className="text-center">
            <CheckCircle className="h-12 w-12 text-green-500 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-900 mb-2">
              {language === 'uk' ? 'Email відправлено!' : 'Email Sent!'}
            </h3>
            <p className="text-gray-600 mb-6">
              {language === 'uk' ? 
                'Перевірте свою електронну пошту для інструкцій з відновлення пароля.' :
                'Check your email for password reset instructions.'
              }
            </p>
            <button
              onClick={() => {
                setResetSuccess(false);
                setShowForgotPassword(false);
                setResetEmail('');
              }}
              className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors"
            >
              {language === 'uk' ? 'Повернутися до входу' : 'Back to Login'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg max-w-md w-full">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b">
          <h3 className="text-xl font-semibold text-gray-900">
            {showForgotPassword ? 
              (language === 'uk' ? 'Відновлення пароля' : 'Password Reset') :
              (language === 'uk' ? 'Вхід до акаунту' : 'Account Login')
            }
          </h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
            aria-label={language === 'uk' ? 'Закрити' : 'Close'}
          >
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="p-6">
          {!showForgotPassword ? (
            // Login Form
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label htmlFor="login-identifier" className="block text-sm font-medium text-gray-700 mb-2">
                  {language === 'uk' ? 'Email або номер картки' : 'Email or Card Number'}
                </label>
                <div className="relative">
                  <User className="h-5 w-5 absolute left-3 top-3 text-gray-400" />
                  <input
                    type="text"
                    id="login-identifier"
                    name="identifier"
                    autoComplete="username email"
                    value={formData.identifier}
                    onChange={handleInputChange}
                    className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder={language === 'uk' ? 
                      'ivan@email.com або UKR-001-2024' : 
                      'ivan@email.com or UKR-001-2024'
                    }
                    disabled={isLoading}
                    required
                  />
                </div>
              </div>

              <div>
                <label htmlFor="login-password" className="block text-sm font-medium text-gray-700 mb-2">
                  {language === 'uk' ? 'Пароль' : 'Password'}
                </label>
                <div className="relative">
                  <Lock className="h-5 w-5 absolute left-3 top-3 text-gray-400" />
                  <input
                    type={showPassword ? "text" : "password"}
                    id="login-password"
                    name="password"
                    autoComplete="current-password"
                    value={formData.password}
                    onChange={handleInputChange}
                    className="w-full pl-10 pr-12 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder={language === 'uk' ? 'Введіть пароль' : 'Enter password'}
                    disabled={isLoading}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-3 text-gray-400 hover:text-gray-600"
                    aria-label={showPassword ? 
                      (language === 'uk' ? 'Приховати пароль' : 'Hide password') :
                      (language === 'uk' ? 'Показати пароль' : 'Show password')
                    }
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              {error && (
                <div className="flex items-center p-3 bg-red-50 border border-red-200 rounded-lg" role="alert">
                  <AlertCircle className="h-5 w-5 text-red-500 mr-2 flex-shrink-0" />
                  <p className="text-sm text-red-700">{error}</p>
                </div>
              )}

              <div className="flex items-center justify-between">
                <button
                  type="button"
                  onClick={() => setShowForgotPassword(true)}
                  className="text-sm text-blue-600 hover:text-blue-800"
                >
                  {language === 'uk' ? 'Забули пароль?' : 'Forgot password?'}
                </button>
              </div>

              <div className="space-y-3">
                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
                >
                  {isLoading ? 
                    (language === 'uk' ? 'Вхід...' : 'Signing In...') :
                    (language === 'uk' ? 'Увійти' : 'Sign In')
                  }
                </button>
                
                <button
                  type="button"
                  onClick={onClose}
                  className="w-full border border-gray-300 text-gray-700 py-3 px-4 rounded-lg hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 font-medium"
                >
                  {language === 'uk' ? 'Скасувати' : 'Cancel'}
                </button>
              </div>
            </form>
          ) : (
            // Forgot Password Form
            <form onSubmit={handleForgotPassword} className="space-y-4">
              <div className="text-center mb-6">
                <p className="text-gray-600">
                  {language === 'uk' ? 
                    'Введіть свою email адресу і ми надішлемо інструкції для відновлення пароля.' :
                    'Enter your email address and we\'ll send you password reset instructions.'
                  }
                </p>
              </div>

              <div>
                <label htmlFor="reset-email" className="block text-sm font-medium text-gray-700 mb-2">
                  {language === 'uk' ? 'Email адреса' : 'Email Address'}
                </label>
                <div className="relative">
                  <Mail className="h-5 w-5 absolute left-3 top-3 text-gray-400" />
                  <input
                    type="email"
                    id="reset-email"
                    name="resetEmail"
                    autoComplete="email"
                    value={resetEmail}
                    onChange={(e) => setResetEmail(e.target.value)}
                    className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder={language === 'uk' ? 'ivan@email.com' : 'ivan@email.com'}
                    disabled={isLoading}
                    required
                  />
                </div>
              </div>

              {error && (
                <div className="flex items-center p-3 bg-red-50 border border-red-200 rounded-lg" role="alert">
                  <AlertCircle className="h-5 w-5 text-red-500 mr-2 flex-shrink-0" />
                  <p className="text-sm text-red-700">{error}</p>
                </div>
              )}

              <div className="space-y-3">
                <button
                  type="submit"
                  disabled={isLoading}
                  className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
                >
                  {isLoading ? 
                    (language === 'uk' ? 'Відправка...' : 'Sending...') :
                    (language === 'uk' ? 'Відправити інструкції' : 'Send Instructions')
                  }
                </button>
                
                <button
                  type="button"
                  onClick={() => {
                    setShowForgotPassword(false);
                    setResetEmail('');
                    setError('');
                  }}
                  className="w-full border border-gray-300 text-gray-700 py-3 px-4 rounded-lg hover:bg-gray-50 focus:ring-2 focus:ring-blue-500 font-medium"
                >
                  {language === 'uk' ? 'Повернутися до входу' : 'Back to Login'}
                </button>
              </div>
            </form>
          )}

          {/* Info Section */}
          <div className="mt-6 p-4 bg-blue-50 rounded-lg">
            <h4 className="text-sm font-medium text-blue-900 mb-2">
              {language === 'uk' ? 'Перший раз тут?' : 'First time here?'}
            </h4>
            <p className="text-xs text-blue-800">
              {language === 'uk' ? 
                'Якщо ви зареєстровані в бібліотеці, але не маєте акаунту, зверніться до бібліотекаря для створення облікового запису.' :
                'If you\'re registered with the library but don\'t have an account, please ask a librarian to create your account.'
              }
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PatronLogin;