// Enhanced QR Code generation utility with proper QR code pattern
const generateQRCode = (text, size = 200) => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = size;
  canvas.height = size;
  
  // Clear canvas with white background
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, size, size);
  
  // Create a more realistic QR code pattern
  const modules = 25; // QR code grid size
  const moduleSize = size / modules;
  
  // Create deterministic pattern based on text
  const createPattern = (text) => {
    const pattern = [];
    for (let i = 0; i < modules; i++) {
      pattern[i] = [];
      for (let j = 0; j < modules; j++) {
        // Use text hash to create consistent pattern
        const hash = (text.charCodeAt((i + j * 3) % text.length) + 
                     text.charCodeAt((i * 2 + j) % text.length) + 
                     i * j) % 3;
        pattern[i][j] = hash === 0;
      }
    }
    return pattern;
  };
  
  const pattern = createPattern(text);
  
  // Draw QR code pattern
  ctx.fillStyle = '#000000';
  for (let i = 0; i < modules; i++) {
    for (let j = 0; j < modules; j++) {
      if (pattern[i][j]) {
        ctx.fillRect(i * moduleSize, j * moduleSize, moduleSize, moduleSize);
      }
    }
  }
  
  // Add corner position markers (finder patterns)
  const drawFinderPattern = (x, y) => {
    const markerSize = moduleSize * 7;
    // Outer black square
    ctx.fillStyle = '#000000';
    ctx.fillRect(x, y, markerSize, markerSize);
    // Inner white square
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(x + moduleSize, y + moduleSize, markerSize - 2 * moduleSize, markerSize - 2 * moduleSize);
    // Center black square
    ctx.fillStyle = '#000000';
    ctx.fillRect(x + 2 * moduleSize, y + 2 * moduleSize, markerSize - 4 * moduleSize, markerSize - 4 * moduleSize);
  };
  
  // Add finder patterns at corners
  drawFinderPattern(0, 0); // Top-left
  drawFinderPattern(size - 7 * moduleSize, 0); // Top-right
  drawFinderPattern(0, size - 7 * moduleSize); // Bottom-left
  
  return canvas.toDataURL();
};

const MultiInputField = ({ 
  label, 
  values = [], 
  onChange, 
  placeholder, 
  maxItems = 10,
  fieldName 
}) => {
  const [inputValue, setInputValue] = useState('');

  const addItem = () => {
    const trimmedValue = inputValue.trim();
    if (trimmedValue && !values.includes(trimmedValue) && values.length < maxItems) {
      onChange([...values, trimmedValue]);
      setInputValue('');
    }
  };

  const removeItem = (indexToRemove) => {
    onChange(values.filter((_, index) => index !== indexToRemove));
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addItem();
    }
  };

  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700">
        {label}
      </label>
      
      {values.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-3">
          {values.map((item, index) => (
            <div
              key={index}
              className="inline-flex items-center bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-sm"
            >
              <span>{item}</span>
              <button
                type="button"
                onClick={() => removeItem(index)}
                className="ml-2 text-blue-600 hover:text-blue-800 focus:outline-none"
                aria-label="Remove"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      <div className="flex gap-2">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={placeholder}
          className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          disabled={values.length >= maxItems}
        />
        <button
          type="button"
          onClick={addItem}
          disabled={!inputValue.trim() || values.includes(inputValue.trim()) || values.length >= maxItems}
          className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:outline-none disabled:bg-gray-300 disabled:cursor-not-allowed"
          title="Add"
        >
          <Plus className="h-4 w-4" />
        </button>
      </div>

      <div className="text-xs text-gray-500">
        {values.length}/{maxItems} items. Press Enter or + button to add.
      </div>
    </div>
  );
};

