// components/SEOHelmet.js
import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

const SEOHelmet = ({ 
  title, 
  description, 
  keywords,
  canonicalUrl,
  ogImage,
  structuredData,
  currentView = 'catalog',
  searchQuery = '',
  bookData = null 
}) => {
  const { language } = useLanguage();

  // Default SEO values
  const defaultTitle = language === 'uk' 
    ? 'Українська Бібліотека - Лондон, Онтаріо | Каталог Книг'
    : 'Ukrainian Library Catalog - London, Ontario | Українська Бібліотека';

  const defaultDescription = language === 'uk'
    ? 'Відкрийте українську літературу та культуру в Українській Бібліотеці Лондона. Переглядайте наш цифровий каталог класичних та сучасних українських книг, резервуйте видання та досліджуйте нашу двомовну колекцію.'
    : 'Discover Ukrainian literature and culture at London\'s Ukrainian Library. Browse our digital catalog of classic and contemporary Ukrainian books, reserve titles, and explore our bilingual collection.';

  const defaultKeywords = language === 'uk'
    ? 'українська бібліотека, українські книги, Лондон Онтаріо, українська література, українська культура, цифровий каталог бібліотеки, українська діаспора, Шевченко, українські автори, двомовна бібліотека'
    : 'Ukrainian library, Ukrainian books, London Ontario, Ukrainian literature, Ukrainian culture, digital library catalog, Ukrainian diaspora, Shevchenko, Ukrainian authors, bilingual library';

  // Dynamic title generation based on context
  const generateTitle = () => {
    if (bookData) {
      const bookTitle = bookData.title;
      const author = bookData.authors?.[0] || bookData.author || '';
      if (language === 'uk') {
        return `${bookTitle}${author ? ` - ${author}` : ''} | Українська Бібліотека Лондон`;
      }
      return `${bookTitle}${author ? ` by ${author}` : ''} | Ukrainian Library London`;
    }

    if (searchQuery) {
      if (language === 'uk') {
        return `Пошук: "${searchQuery}" | Українська Бібліотека Лондон`;
      }
      return `Search: "${searchQuery}" | Ukrainian Library London`;
    }

    if (currentView === 'admin') {
      if (language === 'uk') {
        return `Панель Адміністратора | Українська Бібліотека Лондон`;
      }
      return `Admin Dashboard | Ukrainian Library London`;
    }

    return title || defaultTitle;
  };

  // Dynamic description generation
  const generateDescription = () => {
    if (bookData) {
      const bookTitle = bookData.title;
      const author = bookData.authors?.[0] || bookData.author || '';
      const genre = bookData.genre || '';
      
      if (language === 'uk') {
        return `Читайте "${bookTitle}"${author ? ` автора ${author}` : ''}${genre ? ` в жанрі ${genre}` : ''} в Українській Бібліотеці Лондона. Резервуйте цю книгу онлайн.`;
      }
      return `Read "${bookTitle}"${author ? ` by ${author}` : ''}${genre ? ` in ${genre} genre` : ''} at Ukrainian Library London. Reserve this book online.`;
    }

    if (searchQuery) {
      if (language === 'uk') {
        return `Результати пошуку для "${searchQuery}" в каталозі Української Бібліотеки Лондона. Знайдіть українські книги, автори та жанри.`;
      }
      return `Search results for "${searchQuery}" in Ukrainian Library London catalog. Find Ukrainian books, authors, and genres.`;
    }

    return description || defaultDescription;
  };

  // Generate structured data for books
  const generateBookStructuredData = () => {
    if (!bookData) return null;

    return {
      "@context": "https://schema.org",
      "@type": "Book",
      "name": bookData.title,
      "author": bookData.authors || [bookData.author],
      "genre": bookData.genre,
      "datePublished": bookData.publishedYear || bookData.year,
      "publisher": bookData.publisher,
      "isbn": bookData.isbn,
      "numberOfPages": bookData.pages,
      "inLanguage": bookData.language || ["uk", "en"],
      "about": bookData.subjects || [],
      "isPartOf": {
        "@type": "Collection",
        "name": "Ukrainian Library London Ontario Collection"
      },
      "offers": {
        "@type": "Offer",
        "availability": bookData.status === 'available' 
          ? "https://schema.org/InStock" 
          : "https://schema.org/OutOfStock",
        "price": "0",
        "priceCurrency": "CAD"
      }
    };
  };

  const finalTitle = generateTitle();
  const finalDescription = generateDescription();
  const finalKeywords = keywords || defaultKeywords;

  React.useEffect(() => {
    // Update document title
    document.title = finalTitle;

    // Update meta description
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.name = 'description';
      document.head.appendChild(metaDescription);
    }
    metaDescription.content = finalDescription;

    // Update meta keywords
    let metaKeywords = document.querySelector('meta[name="keywords"]');
    if (!metaKeywords) {
      metaKeywords = document.createElement('meta');
      metaKeywords.name = 'keywords';
      document.head.appendChild(metaKeywords);
    }
    metaKeywords.content = finalKeywords;

    // Update Open Graph title
    let ogTitle = document.querySelector('meta[property="og:title"]');
    if (!ogTitle) {
      ogTitle = document.createElement('meta');
      ogTitle.setAttribute('property', 'og:title');
      document.head.appendChild(ogTitle);
    }
    ogTitle.content = finalTitle;

    // Update Open Graph description
    let ogDescription = document.querySelector('meta[property="og:description"]');
    if (!ogDescription) {
      ogDescription = document.createElement('meta');
      ogDescription.setAttribute('property', 'og:description');
      document.head.appendChild(ogDescription);
    }
    ogDescription.content = finalDescription;

    // Update Twitter title
    let twitterTitle = document.querySelector('meta[property="twitter:title"]');
    if (!twitterTitle) {
      twitterTitle = document.createElement('meta');
      twitterTitle.setAttribute('property', 'twitter:title');
      document.head.appendChild(twitterTitle);
    }
    twitterTitle.content = finalTitle;

    // Update Twitter description
    let twitterDescription = document.querySelector('meta[property="twitter:description"]');
    if (!twitterDescription) {
      twitterDescription = document.createElement('meta');
      twitterDescription.setAttribute('property', 'twitter:description');
      document.head.appendChild(twitterDescription);
    }
    twitterDescription.content = finalDescription;

    // Update canonical URL if provided
    if (canonicalUrl) {
      let canonical = document.querySelector('link[rel="canonical"]');
      if (!canonical) {
        canonical = document.createElement('link');
        canonical.rel = 'canonical';
        document.head.appendChild(canonical);
      }
      canonical.href = canonicalUrl;
    }

    // Update HTML lang attribute
    document.documentElement.lang = language === 'uk' ? 'uk' : 'en';

    // Add/update structured data for books
    const bookStructuredData = generateBookStructuredData();
    if (bookStructuredData) {
      // Remove existing book structured data
      const existingBookScript = document.querySelector('script[data-book-structured-data]');
      if (existingBookScript) {
        existingBookScript.remove();
      }

      // Add new book structured data
      const script = document.createElement('script');
      script.type = 'application/ld+json';
      script.setAttribute('data-book-structured-data', 'true');
      script.textContent = JSON.stringify(bookStructuredData);
      document.head.appendChild(script);
    }

    // Cleanup function
    return () => {
      // Remove book structured data when component unmounts
      const bookScript = document.querySelector('script[data-book-structured-data]');
      if (bookScript) {
        bookScript.remove();
      }
    };
  }, [finalTitle, finalDescription, finalKeywords, canonicalUrl, language, bookData]);

  // This component doesn't render anything visible
  return null;
};

export default SEOHelmet;