import React, { useState, useRef, useEffect } from 'react';
import { Book, Users, Plus, LogOut, ChevronDown, ChevronRight, Camera, User, BookOpen, X } from 'lucide-react';
import { useBooks } from '../hooks/useBooks';
import { usePatrons } from '../hooks/usePatrons';
import { usePatronAuth } from '../contexts/PatronAuthContext';
import { useLanguage } from '../contexts/LanguageContext';
import BookCard from './BookCard';
import BookForm from './BookForm';
import PatronForm from './PatronForm';
import LanguageToggle from './LanguageToggle';
import jsQR from 'jsqr';

const AdminDashboard = ({ onLogout }) => {
  const { books, loading: booksLoading, addBook, updateBook, deleteBook, checkoutBook, returnBook } = useBooks();
  const { patrons, loading: patronsLoading, updatePatron, deletePatron } = usePatrons();
  const { createPatronAccount, isLoading: creatingPatron } = usePatronAuth();
  const { language } = useLanguage();
  
  // Main state
  const [activeTab, setActiveTab] = useState('books');
  const [searchTerm, setSearchTerm] = useState('');
  
  // Modal state - only one modal can be open at a time
  const [currentModal, setCurrentModal] = useState(null); // 'addBook', 'editBook', 'addPatron', 'editPatron'
  const [editingBook, setEditingBook] = useState(null);
  const [editingPatron, setEditingPatron] = useState(null);
  
  // Messages
  const [patronMessage, setPatronMessage] = useState('');
  const [bookMessage, setBookMessage] = useState('');
  
  // Patron expansion state
  const [expandedPatrons, setExpandedPatrons] = useState(new Set());
  
  // Checkout scanner state
  const [isScanning, setIsScanning] = useState(false);
  const [scanType, setScanType] = useState('patron');
  const [selectedPatron, setSelectedPatron] = useState(null);
  const [scannedBooks, setScannedBooks] = useState([]);
  const [checkoutMessage, setCheckoutMessage] = useState('');
  const [videoStream, setVideoStream] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  // Translations
  const t = {
    // Header
    libraryAdmin: language === 'uk' ? 'Адміністрування Бібліотеки' : 'Library Admin',
    logout: language === 'uk' ? 'Вийти' : 'Logout',
    
    // Tabs
    books: language === 'uk' ? 'Книги' : 'Books',
    patrons: language === 'uk' ? 'Читачі' : 'Patrons',
    checkoutScanner: language === 'uk' ? 'Сканер Видачі' : 'Checkout Scanner',
    
    // Search and actions
    searchBooks: language === 'uk' ? 'Пошук книг...' : 'Search books...',
    searchPatrons: language === 'uk' ? 'Пошук читачів...' : 'Search patrons...',
    addBook: language === 'uk' ? 'Додати Книгу' : 'Add Book',
    addPatron: language === 'uk' ? 'Додати Читача' : 'Add Patron',
    creating: language === 'uk' ? 'Створення...' : 'Creating...',
    
    // Table headers
    name: language === 'uk' ? 'Ім\'я' : 'Name',
    email: language === 'uk' ? 'Email' : 'Email',
    joinDate: language === 'uk' ? 'Дата Реєстрації' : 'Join Date',
    checkedOut: language === 'uk' ? 'Видано' : 'Checked Out',
    actions: language === 'uk' ? 'Дії' : 'Actions',
    
    // Status
    book: language === 'uk' ? 'книга' : 'book',
    books: language === 'uk' ? 'книг' : 'books',
    edit: language === 'uk' ? 'Редагувати' : 'Edit',
    delete: language === 'uk' ? 'Видалити' : 'Delete',
    close: language === 'uk' ? 'Закрити' : 'Close',
    
    // Checkout scanner
    automatedCheckoutScanner: language === 'uk' ? 'Автоматизований Сканер Видачі' : 'Automated Checkout Scanner',
    scanPatronCards: language === 'uk' ? 'Скануйте картки читачів та штрихкоди книг для швидкої видачі' : 'Scan patron cards and book barcodes for quick checkout',
    startScanner: language === 'uk' ? 'Запустити Сканер' : 'Start Scanner',
    stopScanner: language === 'uk' ? 'Зупинити Сканер' : 'Stop Scanner',
    reset: language === 'uk' ? 'Скинути' : 'Reset',
    
    // Scanner status
    cameraStatus: language === 'uk' ? 'Статус камери' : 'Camera Status',
    active: language === 'uk' ? 'Активна' : 'Active',
    inactive: language === 'uk' ? 'Неактивна' : 'Inactive',
    scanning: language === 'uk' ? 'Сканування' : 'Scanning',
    yes: language === 'uk' ? 'Так' : 'Yes',
    no: language === 'uk' ? 'Ні' : 'No',
    
    // Scanner steps
    step1ScanPatron: language === 'uk' ? 'Крок 1: Сканувати Картку Читача' : 'Step 1: Scan Patron Card',
    step2ScanBooks: language === 'uk' ? 'Крок 2: Сканувати Книги' : 'Step 2: Scan Books',
    
    // Messages
    patronFound: language === 'uk' ? 'Читача знайдено' : 'Patron found',
    nowScanBooks: language === 'uk' ? 'Тепер скануйте книги для видачі.' : 'Now scan books to check out.',
    noPatronFound: language === 'uk' ? 'Читача не знайдено для' : 'No patron found for',
    bookNotRecognized: language === 'uk' ? 'Книгу не розпізнано. Спробуйте сканувати знову або перевірте, чи є ця книга в системі.' : 'Book not recognized. Please try scanning again or check if this book is in the system.',
    alreadyScanned: language === 'uk' ? 'вже просканована для цієї видачі' : 'already scanned for this checkout',
    notAvailable: language === 'uk' ? 'недоступна (зараз видана)' : 'is not available (currently checked out)',
    addedToCheckout: language === 'uk' ? 'Додано до списку видачі' : 'Added to checkout list',
    successfullyCheckedOut: language === 'uk' ? 'Успішно видано' : 'Successfully checked out',
    booksTo: language === 'uk' ? 'книг' : 'book(s) to',
    checkoutError: language === 'uk' ? 'Помилка видачі' : 'Checkout error',
    
    // Patron details
    selectedPatron: language === 'uk' ? 'Обраний Читач:' : 'Selected Patron:',
    memberSince: language === 'uk' ? 'Член з' : 'Member since',
    currentlyCheckedOut: language === 'uk' ? 'Зараз видано:' : 'Currently Checked Out:',
    noBooksCheckedOut: language === 'uk' ? 'Зараз немає виданих книг' : 'No books currently checked out',
    
    // Book checkout list
    booksToCheckout: language === 'uk' ? 'Книги для видачі' : 'Books to Checkout',
    by: language === 'uk' ? 'автор' : 'by',
    remove: language === 'uk' ? 'Видалити' : 'Remove',
    completeCheckout: language === 'uk' ? 'Завершити Видачу' : 'Complete Checkout',
    
    // Instructions
    instructions: language === 'uk' ? 'Інструкції:' : 'Instructions:',
    instruction1: language === 'uk' ? 'Натисніть "Запустити Сканер" для активації камери' : 'Click "Start Scanner" to activate the camera',
    instruction2: language === 'uk' ? 'Спочатку скануйте бібліотечну картку або QR-код читача' : 'First, scan the patron\'s library card or QR code',
    instruction3: language === 'uk' ? 'Після знаходження читача, скануйте штрих-код або QR-код кожної книги' : 'Once patron is found, scan each book\'s barcode or QR code',
    instruction4: language === 'uk' ? 'Перегляньте прочитані книги та натисніть "Завершити Видачу"' : 'Review the scanned books and click "Complete Checkout"',
    instruction5: language === 'uk' ? 'Використовуйте "Скинути" для початку роботи з новим читачем' : 'Use "Reset" to start over with a new patron',
    
    // Due dates and status
    due: language === 'uk' ? 'Повернути до' : 'Due',
    overdue: language === 'uk' ? 'ПРОСТРОЧЕНО' : 'OVERDUE',
    dueSoon: language === 'uk' ? 'СКОРО СТРОК' : 'DUE SOON',
    returnBook: language === 'uk' ? 'Повернути Книгу' : 'Return Book',
    
    // Patron management messages
    patronCreatedSuccessfully: language === 'uk' ? 'Читача успішно створено!' : 'Patron created successfully!',
    bookCreatedSuccessfully: language === 'uk' ? 'Книгу успішно створено!' : 'Book created successfully!',
    emailSentSuccessfully: language === 'uk' ? 'Email успішно надіслано.' : 'Welcome email sent.',
    emailFailed: language === 'uk' ? 'Email не вдалося надіслати - перевірте консоль.' : 'Email failed - check console.',
    error: language === 'uk' ? 'Помилка' : 'Error',
    
    // Patron checkout summary
    checkedOutBooks: language === 'uk' ? 'Видані Книги' : 'Checked Out Books',
    isbn: language === 'uk' ? 'ISBN' : 'ISBN',
    to: language === 'uk' ? 'Кому' : 'To',
    
    // Loading and states
    loading: language === 'uk' ? 'Завантаження...' : 'Loading...',
    videoReady: language === 'uk' ? 'Відео готове' : 'Video Ready',
    
    // Test QR
    testQRCode: language === 'uk' ? 'Тестовий QR код' : 'Test QR Code',
    useThisQR: language === 'uk' ? 'Використайте цей QR код для тестування сканування ЧИТАЧА:' : 'Use this QR code to test PATRON scanning:',
    contains: language === 'uk' ? 'Містить' : 'Contains',
    makeSurePatronMode: language === 'uk' ? 'Переконайтеся, що ви в режимі "Крок 1: Сканувати Картку Читача"' : 'Make sure you\'re in "Step 1: Scan Patron Card" mode'
  };

  // Modal handlers
  const closeAllModals = () => {
    setCurrentModal(null);
    setEditingBook(null);
    setEditingPatron(null);
    setPatronMessage('');
    setBookMessage('');
  };

  const openAddBookModal = () => {
    closeAllModals();
    setCurrentModal('addBook');
  };

  const openEditBookModal = (book) => {
    closeAllModals();
    setEditingBook(book);
    setCurrentModal('editBook');
  };

  const openAddPatronModal = () => {
    closeAllModals();
    setCurrentModal('addPatron');
  };

  const openEditPatronModal = (patron) => {
    closeAllModals();
    setEditingPatron(patron);
    setCurrentModal('editPatron');
  };

  // Book handlers
  const handleAddBook = async (bookData) => {
    try {
      await addBook(bookData);
      setBookMessage(`✅ ${t.bookCreatedSuccessfully}`);
      closeAllModals();
      setTimeout(() => setBookMessage(''), 3000);
    } catch (error) {
      setBookMessage(`❌ ${t.error}: ${error.message}`);
    }
  };

  const handleUpdateBook = async (bookData) => {
    try {
      await updateBook(editingBook.id, bookData);
      setBookMessage(`✅ Book updated successfully!`);
      closeAllModals();
      setTimeout(() => setBookMessage(''), 3000);
    } catch (error) {
      setBookMessage(`❌ ${t.error}: ${error.message}`);
    }
  };

  // Patron handlers
  const handleCreatePatron = async (formData) => {
    setPatronMessage('');
    
    try {
      const patronData = {
        ...formData,
        membershipType: formData.membershipType || 'Member'
      };
      
      const result = await createPatronAccount(patronData);
      
      if (result.success) {
        setPatronMessage(`✅ ${t.patronCreatedSuccessfully} ${result.emailSent ? t.emailSentSuccessfully : t.emailFailed}`);
        closeAllModals();
        
        if (result.password) {
          console.log('Generated password for admin:', result.password);
        }
        
        setTimeout(() => setPatronMessage(''), 5000);
      } else {
        setPatronMessage(`❌ ${t.error}: ${result.error}`);
      }
    } catch (error) {
      console.error('Error in handleCreatePatron:', error);
      setPatronMessage(`❌ ${t.error}: ${error.message}`);
    }
  };

  const handleUpdatePatron = async (patronData) => {
    try {
      await updatePatron(editingPatron.id, patronData);
      setPatronMessage(`✅ Patron updated successfully!`);
      closeAllModals();
      setTimeout(() => setPatronMessage(''), 3000);
    } catch (error) {
      setPatronMessage(`❌ ${t.error}: ${error.message}`);
    }
  };

  // Toggle patron expansion
  const togglePatronExpansion = (patronId) => {
    const newExpanded = new Set(expandedPatrons);
    if (newExpanded.has(patronId)) {
      newExpanded.delete(patronId);
    } else {
      newExpanded.add(patronId);
    }
    setExpandedPatrons(newExpanded);
  };

  // Scanner useEffects
  useEffect(() => {
    if (isScanning && videoRef.current && canvasRef.current) {
      startScanningLoop();
    }
  }, [isScanning]);

  useEffect(() => {
    return () => {
      if (videoStream) {
        videoStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [videoStream]);

  // Scanner functions
  const startScanner = async () => {
    try {
      setCheckoutMessage('');
      
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error(language === 'uk' ? 'Камера не підтримується в цьому браузері' : 'Camera not supported in this browser');
      }
      
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        } 
      });
      
      setVideoStream(stream);
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        
        const video = videoRef.current;
        
        const handleVideoReady = () => {
          setIsScanning(true);
        };
        
        video.onloadedmetadata = handleVideoReady;
        video.oncanplay = handleVideoReady;
        video.onplaying = handleVideoReady;
        
        setTimeout(() => {
          if (!isScanning && videoStream) {
            setIsScanning(true);
          }
        }, 1000);
        
        video.play().catch(console.error);
      }
    } catch (error) {
      console.error('Camera error:', error);
      setCheckoutMessage(`❌ ${t.error}: ${error.message}`);
    }
  };

  const stopScanner = () => {
    if (videoStream) {
      videoStream.getTracks().forEach(track => track.stop());
      setVideoStream(null);
    }
    setIsScanning(false);
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const startScanningLoop = () => {
    let frameCount = 0;
    let animationId = null;
    
    const scanFrame = () => {
      if (!isScanning || !videoRef.current || !canvasRef.current) {
        if (animationId) cancelAnimationFrame(animationId);
        return;
      }
      
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      
      if (video.readyState === video.HAVE_ENOUGH_DATA) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        context.drawImage(video, 0, 0);
        
        frameCount++;
        
        try {
          const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height);
          if (code) {
            if (animationId) cancelAnimationFrame(animationId);
            setIsScanning(false);
            handleScanResult(code.data);
            
            setTimeout(() => {
              if (videoStream && (!selectedPatron || (selectedPatron && scanType === 'book'))) {
                setIsScanning(true);
              }
            }, 2000);
            return;
          }
        } catch (error) {
          console.error('Scan error:', error);
        }
      }
      
      if (isScanning) {
        animationId = requestAnimationFrame(scanFrame);
      }
    };
    
    animationId = requestAnimationFrame(scanFrame);
  };

  const handleScanResult = (data) => {
    if (scanType === 'patron') {
      const patron = patrons.find(p => 
        data.includes(p.id) || 
        data.includes(p.email) || 
        data.includes(p.name) ||
        p.cardId === data ||
        data.includes('TEST_PATRON')
      );
      
      if (patron) {
        setSelectedPatron(patron);
        setScanType('book');
        setCheckoutMessage(`✅ ${t.patronFound}: ${patron.name}. ${t.nowScanBooks}`);
      } else {
        if (data.includes('TEST_PATRON')) {
          const mockPatron = { id: 'test', name: 'Test Patron', email: 'test@library.com' };
          setSelectedPatron(mockPatron);
          setScanType('book');
          setCheckoutMessage(`✅ ${t.patronFound}. ${t.nowScanBooks}`);
        } else {
          setCheckoutMessage(`❌ ${t.noPatronFound}: "${data.substring(0, 50)}...". ${language === 'uk' ? 'Переконайтеся, що ви скануєте картку читача, а не книгу.' : 'Make sure you\'re scanning a patron card, not a book.'}`);
        }
      }
    } else if (scanType === 'book') {
      const book = books.find(b => 
        data.includes(b.isbn) || 
        data.includes(b.id) ||
        b.barcode === data ||
        data.includes('TEST_BOOK')
      );
      
      if (book) {
        if (scannedBooks.find(b => b.id === book.id)) {
          setCheckoutMessage(`❌ "${book.title}" ${t.alreadyScanned}`);
        } 
        else if (book.checkedOutBy) {
          setCheckoutMessage(`❌ "${book.title}" ${t.notAvailable}`);
        } 
        else {
          setScannedBooks(prev => [...prev, book]);
          setCheckoutMessage(`✅ ${t.addedToCheckout} "${book.title}"`);
        }
      } else {
        if (data.includes('TEST_BOOK')) {
          const mockBook = { 
            id: 'test-book-' + Date.now(), 
            title: 'Test Book', 
            author: 'Test Author', 
            isbn: '123456789',
            checkedOutBy: null
          };
          setScannedBooks(prev => [...prev, mockBook]);
          setCheckoutMessage(`✅ ${t.addedToCheckout}`);
        } else {
          setCheckoutMessage(`❌ ${t.bookNotRecognized}`);
        }
      }
    }
  };

  const removeScannedBook = (bookId) => {
    setScannedBooks(prev => prev.filter(b => b.id !== bookId));
  };

  const completeCheckout = async () => {
    if (!selectedPatron || scannedBooks.length === 0) return;
    
    try {
      for (const book of scannedBooks) {
        await checkoutBook(book.id, selectedPatron.name);
      }
      
      setCheckoutMessage(`✅ ${t.successfullyCheckedOut} ${scannedBooks.length} ${t.booksTo} ${selectedPatron.name}`);
      setScannedBooks([]);
      setSelectedPatron(null);
      setScanType('patron');
      
      setTimeout(() => setCheckoutMessage(''), 3000);
    } catch (error) {
      setCheckoutMessage(`❌ ${t.checkoutError}: ${error.message}`);
    }
  };

  const resetCheckout = () => {
    setSelectedPatron(null);
    setScannedBooks([]);
    setScanType('patron');
    setCheckoutMessage('');
  };

  // Filtered data
  const filteredBooks = books.filter(book =>
    book.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    book.author.toLowerCase().includes(searchTerm.toLowerCase()) ||
    book.genre.toLowerCase().includes(searchTerm.toLowerCase()) ||
    book.isbn.includes(searchTerm)
  );

  const filteredPatrons = patrons.filter(patron =>
    patron.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    patron.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPatronCheckedOutBooks = (patronName) => {
    return books.filter(book => book.checkedOutBy === patronName);
  };

  // Loading state
  if (booksLoading || patronsLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-600"></div>
          <p className="mt-4 text-gray-600">{t.loading}</p>
        </div>
      </div>
    );
  }

  // Modal Component
  const Modal = ({ isOpen, onClose, title, children }) => {
    if (!isOpen) return null;

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
        <div className="bg-white rounded-lg max-w-2xl w-full max-h-[90vh] overflow-y-auto">
          <div className="flex justify-between items-center p-6 border-b">
            <h2 className="text-xl font-bold text-gray-900">{title}</h2>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600"
            >
              <X className="h-6 w-6" />
            </button>
          </div>
          <div className="p-6">
            {children}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-6">
            <div className="flex items-center">
              <Book className="h-8 w-8 text-blue-600 mr-3" />
              <h1 className="text-3xl font-bold text-gray-900">{t.libraryAdmin}</h1>
            </div>
            <div className="flex items-center space-x-4">
              <LanguageToggle />
              <button
                onClick={onLogout}
                className="flex items-center text-gray-600 hover:text-red-600 transition-colors"
              >
                <LogOut className="h-4 w-4 mr-2" />
                {t.logout}
              </button>
            </div>
          </div>
          
          {/* Tabs */}
          <div className="flex space-x-8">
            <button
              onClick={() => setActiveTab('books')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === 'books'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              <Book className="h-4 w-4 inline mr-2" />
              {t.books} ({books.length})
            </button>
            <button
              onClick={() => setActiveTab('patrons')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === 'patrons'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              <Users className="h-4 w-4 inline mr-2" />
              {t.patrons} ({patrons.length})
            </button>
            <button
              onClick={() => setActiveTab('checkout')}
              className={`pb-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === 'checkout'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              <BookOpen className="h-4 w-4 inline mr-2" />
              {t.checkoutScanner}
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Books Tab */}
        {activeTab === 'books' && (
          <div>
            {/* Books Header */}
            <div className="flex justify-between items-center mb-6">
              <input
                type="text"
                placeholder={t.searchBooks}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-64 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <button
                onClick={openAddBookModal}
                className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition-colors flex items-center"
              >
                <Plus className="h-4 w-4 mr-2" />
                {t.addBook}
              </button>
            </div>

            {/* Book Messages */}
            {bookMessage && (
              <div className={`mb-4 p-3 rounded-md transition-all ${
                bookMessage.includes('✅') ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
              }`}>
                {bookMessage}
              </div>
            )}

            {/* Books Grid */}
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
              {filteredBooks.map(book => (
                <BookCard 
                  key={book.id} 
                  book={book} 
                  patrons={patrons}
                  onEdit={openEditBookModal}
                  onDelete={deleteBook}
                  onCheckout={checkoutBook}
                  onReturn={returnBook}
                />
              ))}
            </div>

            {/* No books message */}
            {filteredBooks.length === 0 && (
              <div className="text-center py-12">
                <Book className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500">
                  {searchTerm ? 'No books found matching your search.' : 'No books available. Add some books to get started!'}
                </p>
              </div>
            )}
          </div>
        )}

        {/* Patrons Tab */}
        {activeTab === 'patrons' && (
          <div>
            {/* Patrons Header */}
            <div className="flex justify-between items-center mb-6">
              <input
                type="text"
                placeholder={t.searchPatrons}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-64 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <button
                onClick={openAddPatronModal}
                className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition-colors flex items-center"
                disabled={creatingPatron}
              >
                <Plus className="h-4 w-4 mr-2" />
                {creatingPatron ? t.creating : t.addPatron}
              </button>
            </div>

            {/* Patron Messages */}
            {patronMessage && (
              <div className={`mb-4 p-3 rounded-md transition-all ${
                patronMessage.includes('✅') ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
              }`}>
                {patronMessage}
              </div>
            )}

            {/* Patrons Table */}
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="w-8 px-6 py-3"></th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t.name}</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t.email}</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t.joinDate}</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t.checkedOut}</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t.actions}</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {filteredPatrons.map(patron => {
                    const checkedOutBooks = getPatronCheckedOutBooks(patron.name);
                    const isExpanded = expandedPatrons.has(patron.id);
                    
                    return (
                      <React.Fragment key={patron.id}>
                        <tr className="hover:bg-gray-50 transition-colors">
                          <td className="px-6 py-4 whitespace-nowrap">
                            {checkedOutBooks.length > 0 && (
                              <button
                                onClick={() => togglePatronExpansion(patron.id)}
                                className="text-gray-400 hover:text-gray-600 transition-colors"
                              >
                                {isExpanded ? (
                                  <ChevronDown className="h-4 w-4" />
                                ) : (
                                  <ChevronRight className="h-4 w-4" />
                                )}
                              </button>
                            )}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                            {patron.name}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            {patron.email}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            {patron.joinDate}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                              checkedOutBooks.length === 0 
                                ? 'bg-green-100 text-green-800' 
                                : checkedOutBooks.length <= 2
                                ? 'bg-yellow-100 text-yellow-800'
                                : 'bg-red-100 text-red-800'
                            }`}>
                              {checkedOutBooks.length} {checkedOutBooks.length !== 1 ? t.books : t.book}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                            <button
                              onClick={() => openEditPatronModal(patron)}
                              className="text-blue-600 hover:text-blue-900 mr-4 transition-colors"
                            >
                              {t.edit}
                            </button>
                            <button
                              onClick={() => deletePatron(patron.id)}
                              className="text-red-600 hover:text-red-900 transition-colors"
                            >
                              {t.delete}
                            </button>
                          </td>
                        </tr>
                        
                        {/* Expanded row showing checked out books */}
                        {isExpanded && checkedOutBooks.length > 0 && (
                          <tr>
                            <td colSpan="6" className="px-6 py-4 bg-gray-50">
                              <div className="ml-8">
                                <h4 className="text-sm font-medium text-gray-900 mb-3">
                                  📚 {t.checkedOutBooks} ({checkedOutBooks.length})
                                </h4>
                                <div className="space-y-2">
                                  {checkedOutBooks.map(book => (
                                    <div key={book.id} className="bg-white rounded-lg p-3 border border-gray-200">
                                      <div className="flex justify-between items-start">
                                        <div className="flex-1">
                                          <div className="flex items-center space-x-3">
                                            <div className="text-sm">
                                              <p className="font-medium text-gray-900">{book.title}</p>
                                              <p className="text-gray-500">{t.by} {book.author}</p>
                                              <p className="text-xs text-gray-400">{t.isbn}: {book.isbn}</p>
                                            </div>
                                          </div>
                                          {book.dueDate && (
                                            <div className="mt-2">
                                              <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                                                new Date(book.dueDate) < new Date() 
                                                  ? 'bg-red-100 text-red-800' 
                                                  : 'bg-blue-100 text-blue-800'
                                              }`}>
                                                {t.due}: {book.dueDate}
                                                {new Date(book.dueDate) < new Date() && ` (${t.overdue})`}
                                              </span>
                                            </div>
                                          )}
                                        </div>
                                        <div className="ml-4">
                                          <button
                                            onClick={() => returnBook(book.id)}
                                            className="bg-green-600 text-white px-3 py-1 rounded-md text-sm hover:bg-green-700 transition-colors"
                                          >
                                            {t.returnBook}
                                          </button>
                                        </div>
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    );
                  })}
                </tbody>
              </table>

              {/* No patrons message */}
              {filteredPatrons.length === 0 && (
                <div className="text-center py-12">
                  <Users className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-500">
                    {searchTerm ? 'No patrons found matching your search.' : 'No patrons registered. Add some patrons to get started!'}
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Checkout Scanner Tab */}
        {activeTab === 'checkout' && (
          <div className="max-w-4xl mx-auto">
            <div className="bg-white rounded-lg shadow-lg overflow-hidden">
              <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-6">
                <h2 className="text-2xl font-bold mb-2">📱 {t.automatedCheckoutScanner}</h2>
                <p className="text-blue-100">{t.scanPatronCards}</p>
              </div>

              <div className="p-6">
                {/* Status Messages */}
                {checkoutMessage && (
                  <div className={`mb-6 p-4 rounded-lg transition-all ${
                    checkoutMessage.includes('✅') ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                  }`}>
                    {checkoutMessage}
                  </div>
                )}

                {/* Scanner Controls */}
                <div className="mb-6">
                  <div className="flex justify-center space-x-4 mb-4">
                    {!isScanning ? (
                      <button
                        onClick={startScanner}
                        className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition-colors flex items-center"
                      >
                        <Camera className="h-5 w-5 mr-2" />
                        {t.startScanner}
                      </button>
                    ) : (
                      <button
                        onClick={stopScanner}
                        className="bg-red-600 text-white px-6 py-3 rounded-lg hover:bg-red-700 transition-colors flex items-center"
                      >
                        {t.stopScanner}
                      </button>
                    )}
                    
                    <button
                      onClick={resetCheckout}
                      className="bg-gray-600 text-white px-6 py-3 rounded-lg hover:bg-gray-700 transition-colors"
                    >
                      {t.reset}
                    </button>
                  </div>

                  {/* Debug Info */}
                  <div className="text-center text-sm text-gray-600 mb-4">
                    {t.cameraStatus}: {videoStream ? `📹 ${t.active}` : `📱 ${t.inactive}`} | 
                    {t.scanning}: {isScanning ? `🔍 ${t.yes}` : `⏸️ ${t.no}`} | 
                    jsQR: {typeof jsQR !== 'undefined' ? '✅ Loaded' : '❌ Missing'} |
                    {t.videoReady}: {videoRef.current?.readyState >= 2 ? `✅ ${t.yes}` : `❌ ${t.no}`}
                  </div>

                  {/* Test QR Code for debugging */}
                  <div className="text-center mb-4">
                    <details className="bg-gray-100 rounded-lg p-4">
                      <summary className="cursor-pointer text-sm font-medium">🧪 {t.testQRCode} ({language === 'uk' ? 'Натисніть для розгортання' : 'Click to expand'})</summary>
                      <div className="mt-4">
                        <p className="text-xs text-gray-600 mb-2">{t.useThisQR}</p>
                        <div className="bg-white p-4 inline-block border rounded">
                          <svg width="120" height="120" viewBox="0 0 25 25" fill="none">
                            <rect width="25" height="25" fill="white"/>
                            <rect x="0" y="0" width="7" height="7" fill="black"/>
                            <rect x="18" y="0" width="7" height="7" fill="black"/>
                            <rect x="0" y="18" width="7" height="7" fill="black"/>
                            <rect x="2" y="2" width="3" height="3" fill="white"/>
                            <rect x="20" y="2" width="3" height="3" fill="white"/>
                            <rect x="2" y="20" width="3" height="3" fill="white"/>
                            <rect x="8" y="0" width="1" height="1" fill="black"/>
                            <rect x="10" y="0" width="1" height="1" fill="black"/>
                            <rect x="12" y="0" width="1" height="1" fill="black"/>
                            <rect x="14" y="0" width="1" height="1" fill="black"/>
                            <rect x="16" y="0" width="1" height="1" fill="black"/>
                            <rect x="8" y="8" width="9" height="9" fill="black"/>
                            <rect x="10" y="10" width="5" height="5" fill="white"/>
                            <rect x="12" y="12" width="1" height="1" fill="black"/>
                          </svg>
                        </div>
                        <p className="text-xs text-gray-500 mt-2">{t.contains}: "TEST_PATRON_123"</p>
                        <p className="text-xs text-red-500 mt-1">⚠️ {t.makeSurePatronMode}</p>
                      </div>
                    </details>
                  </div>

                  {/* Current Scan Type Indicator */}
                  <div className="text-center">
                    <span className={`inline-flex items-center px-4 py-2 rounded-full text-sm font-medium ${
                      scanType === 'patron' ? 'bg-blue-100 text-blue-800' : 'bg-green-100 text-green-800'
                    }`}>
                      {scanType === 'patron' ? (
                        <>
                          <User className="h-4 w-4 mr-2" />
                          {t.step1ScanPatron}
                        </>
                      ) : (
                        <>
                          <Book className="h-4 w-4 mr-2" />
                          {t.step2ScanBooks}
                        </>
                      )}
                    </span>
                  </div>
                </div>

                {/* Camera Video */}
                {videoStream && (
                  <div className="mb-6">
                    <div className="relative max-w-md mx-auto bg-black rounded-lg overflow-hidden">
                      <video
                        ref={videoRef}
                        autoPlay
                        playsInline
                        muted
                        className="w-full h-64 object-cover"
                      />
                      <div className="absolute inset-0 border-4 border-blue-500 rounded-lg pointer-events-none">
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-48 h-24 border-2 border-green-400 rounded-lg bg-green-400 bg-opacity-10"></div>
                      </div>
                      {/* Scanning indicator */}
                      {isScanning && (
                        <div className="absolute top-2 left-2 bg-green-500 text-white px-2 py-1 rounded text-xs">
                          🔍 {t.scanning}...
                        </div>
                      )}
                    </div>
                    {/* Canvas - hidden but always present when video exists */}
                    <canvas ref={canvasRef} className="hidden" />
                  </div>
                )}

                {/* Selected Patron */}
                {selectedPatron && (
                  <div className="mb-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <h3 className="font-medium text-blue-900 mb-3">📋 {t.selectedPatron}</h3>
                    <div className="bg-white rounded-lg p-4 border border-blue-200">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                        <div>
                          <p className="font-semibold text-lg text-blue-900">{selectedPatron.name}</p>
                          <p className="text-sm text-blue-700">{selectedPatron.email}</p>
                          {selectedPatron.joinDate && (
                            <p className="text-xs text-gray-600">{t.memberSince}: {selectedPatron.joinDate}</p>
                          )}
                        </div>
                        <div className="text-right">
                          {selectedPatron.membershipType && (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                              {selectedPatron.membershipType}
                            </span>
                          )}
                        </div>
                      </div>
                      
                      {/* Current Checked Out Books */}
                      {(() => {
                        const currentBooks = getPatronCheckedOutBooks(selectedPatron.name);
                        return (
                          <div>
                            <div className="flex items-center justify-between mb-2">
                              <h4 className="font-medium text-gray-900">{t.currentlyCheckedOut}</h4>
                              <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                                currentBooks.length === 0 
                                  ? 'bg-green-100 text-green-800' 
                                  : currentBooks.length <= 2
                                  ? 'bg-yellow-100 text-yellow-800'
                                  : 'bg-red-100 text-red-800'
                              }`}>
                                {currentBooks.length} {currentBooks.length !== 1 ? t.books : t.book}
                              </span>
                            </div>
                            
                            {currentBooks.length === 0 ? (
                              <p className="text-sm text-gray-500 italic bg-gray-50 p-3 rounded">
                                ✅ {t.noBooksCheckedOut}
                              </p>
                            ) : (
                              <div className="space-y-2 max-h-40 overflow-y-auto bg-gray-50 p-3 rounded">
                                {currentBooks.map(book => (
                                  <div key={book.id} className="bg-white p-2 rounded border text-sm">
                                    <div className="flex justify-between items-start">
                                      <div className="flex-1">
                                        <p className="font-medium text-gray-900">{book.title}</p>
                                        <p className="text-gray-600">{t.by} {book.author}</p>
                                        <p className="text-xs text-gray-500">{t.isbn}: {book.isbn}</p>
                                      </div>
                                      <div className="ml-2 text-right">
                                        {book.dueDate && (
                                          <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${
                                            new Date(book.dueDate) < new Date() 
                                              ? 'bg-red-100 text-red-800' 
                                              : new Date(book.dueDate) <= new Date(Date.now() + 3 * 24 * 60 * 60 * 1000)
                                              ? 'bg-yellow-100 text-yellow-800'
                                              : 'bg-green-100 text-green-800'
                                          }`}>
                                            {new Date(book.dueDate) < new Date() ? t.overdue : 
                                             new Date(book.dueDate) <= new Date(Date.now() + 3 * 24 * 60 * 60 * 1000) ? t.dueSoon : 
                                             `${t.due}: ${book.dueDate}`}
                                          </span>
                                        )}
                                      </div>
                                    </div>
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })()}
                    </div>
                  </div>
                )}

                {/* Scanned Books */}
                {scannedBooks.length > 0 && (
                  <div className="mb-6 bg-green-50 border border-green-200 rounded-lg p-4">
                    <h3 className="font-medium text-green-900 mb-3">{t.booksToCheckout} ({scannedBooks.length}):</h3>
                    <div className="space-y-2">
                      {scannedBooks.map(book => (
                        <div key={book.id} className="flex justify-between items-center bg-white p-3 rounded border">
                          <div>
                            <p className="font-medium">{book.title}</p>
                            <p className="text-sm text-gray-600">{t.by} {book.author} • {t.isbn}: {book.isbn}</p>
                          </div>
                          <button
                            onClick={() => removeScannedBook(book.id)}
                            className="text-red-600 hover:text-red-800 text-sm transition-colors"
                          >
                            {t.remove}
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Complete Checkout Button */}
                {selectedPatron && scannedBooks.length > 0 && (
                  <div className="text-center">
                    <button
                      onClick={completeCheckout}
                      className="bg-green-600 text-white px-8 py-3 rounded-lg hover:bg-green-700 transition-colors font-medium"
                    >
                      {t.completeCheckout} ({scannedBooks.length} {t.books})
                    </button>
                  </div>
                )}

                {/* Instructions */}
                <div className="mt-8 bg-gray-50 rounded-lg p-4">
                  <h3 className="font-medium text-gray-900 mb-2">{t.instructions}</h3>
                  <ol className="list-decimal list-inside text-sm text-gray-700 space-y-1">
                    <li>{t.instruction1}</li>
                    <li>{t.instruction2}</li>
                    <li>{t.instruction3}</li>
                    <li>{t.instruction4}</li>
                    <li>{t.instruction5}</li>
                  </ol>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Modals */}
      <Modal
        isOpen={currentModal === 'addBook'}
        onClose={closeAllModals}
        title={t.addBook}
      >
        <BookForm
          onSubmit={handleAddBook}
          onClose={closeAllModals}
        />
      </Modal>

      <Modal
        isOpen={currentModal === 'editBook'}
        onClose={closeAllModals}
        title={`${t.edit} ${editingBook?.title || ''}`}
      >
        <BookForm
          book={editingBook}
          onSubmit={handleUpdateBook}
          onClose={closeAllModals}
        />
      </Modal>

      <Modal
        isOpen={currentModal === 'addPatron'}
        onClose={closeAllModals}
        title={t.addPatron}
      >
        <PatronForm
          onSubmit={handleCreatePatron}
          onClose={closeAllModals}
          isLoading={creatingPatron}
        />
      </Modal>

      <Modal
        isOpen={currentModal === 'editPatron'}
        onClose={closeAllModals}
        title={`${t.edit} ${editingPatron?.name || ''}`}
      >
        <PatronForm
          patron={editingPatron}
          onSubmit={handleUpdatePatron}
          onClose={closeAllModals}
        />
      </Modal>
    </div>
  );
};

export default AdminDashboard;