// Create reverse mapping (Ukrainian to English)
export const reverseGenreTranslations = Object.fromEntries(
  Object.entries(genreTranslations).map(([en, uk]) => [uk, en])
);

// Function to translate genre based on current language
export const translateGenre = (genre, targetLanguage) => {
  if (!genre) return '';
  
  if (targetLanguage === 'uk') {
    // Translate from English to Ukrainian
    return genreTranslations[genre] || genre;
  } else {
    // Translate from Ukrainian to English
    return reverseGenreTranslations[genre] || genre;
  }
};

// Function to get all available genres in the target language
export const getTranslatedGenres = (genres, targetLanguage) => {
  return genres.map(genre => translateGenre(genre, targetLanguage));
};