// src/contexts/PatronAuthContext.js - Enhanced with debugging (warnings fixed)
import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  where, 
  getDocs, 
  addDoc, 
  updateDoc, 
  doc, 
  onSnapshot,
  orderBy 
} from 'firebase/firestore';
import { db } from '../firebase/config';
import { emailService } from '../services/emailService';

const PatronAuthContext = createContext();

export const usePatronAuth = () => {
  const context = useContext(PatronAuthContext);
  if (!context) {
    throw new Error('usePatronAuth must be used within PatronAuthProvider');
  }
  return context;
};

export const PatronAuthProvider = ({ children }) => {
  const [currentPatron, setCurrentPatron] = useState(null);
  const [allPatrons, setAllPatrons] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Load all patrons for admin interface
  useEffect(() => {
    const q = query(collection(db, 'patrons'), orderBy('name'));
    
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const patronsData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setAllPatrons(patronsData);
    });

    return () => unsubscribe();
  }, []);

  // Check for existing session
  useEffect(() => {
    const savedPatron = localStorage.getItem('currentPatron');
    if (savedPatron) {
      try {
        const patron = JSON.parse(savedPatron);
        setCurrentPatron(patron);
        setIsAuthenticated(true);
      } catch (error) {
        console.error('Error parsing saved patron:', error);
        localStorage.removeItem('currentPatron');
      }
    }
  }, []);

  // Generate unique card number
  const generateCardNumber = (name, membershipType) => {
    const nameCode = name.replace(/\s+/g, '').substring(0, 3).toUpperCase();
    const typeCode = membershipType.substring(0, 3).toUpperCase();
    const timestamp = Date.now().toString().slice(-6);
    const random = Math.floor(Math.random() * 100).toString().padStart(2, '0');
    
    return `UKR-${nameCode}${typeCode}-${timestamp}${random}`;
  };

  // Generate secure password
  const generatePassword = () => {
    const length = 8;
    const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let password = "";
    for (let i = 0; i < length; i++) {
      password += charset.charAt(Math.floor(Math.random() * charset.length));
    }
    return password;
  };

  // Simple password hashing (in production, use proper backend hashing)
  const hashPassword = (password) => {
    return btoa(password + 'salt_key_2024'); // Simple encoding - use proper hashing in production
  };

  // Create patron account - ENHANCED WITH DEBUGGING
  const createPatronAccount = async (patronData, useCustomPassword = false, customPassword = '') => {
    console.log('🎯 STEP 1: createPatronAccount started');
    console.log('🎯 STEP 1: patronData received:', patronData);
    console.log('🎯 STEP 1: useCustomPassword:', useCustomPassword);
    
    setIsLoading(true);
    
    try {
      console.log('🎯 STEP 2: Starting email existence check...');
      
      // Check if email already exists
      const emailQuery = query(
        collection(db, 'patrons'), 
        where('email', '==', patronData.email.toLowerCase())
      );
      const emailSnapshot = await getDocs(emailQuery);
      
      if (!emailSnapshot.empty) {
        console.log('🎯 ERROR: Email already exists:', patronData.email);
        throw new Error('Email address already exists');
      }

      console.log('🎯 STEP 3: Email check passed - generating credentials...');

      // Generate password and card number
      const password = useCustomPassword ? customPassword : generatePassword();
      const cardNumber = generateCardNumber(patronData.name, patronData.membershipType);
      
      console.log('🎯 STEP 3: Generated password:', password);
      console.log('🎯 STEP 3: Generated card number:', cardNumber);
      
      console.log('🎯 STEP 4: Creating patron record...');
      
      // Create patron record
      const newPatron = {
        name: patronData.name.trim(),
        email: patronData.email.toLowerCase().trim(),
        cardNumber: cardNumber,
        password: hashPassword(password), // Store hashed password
        membershipType: patronData.membershipType,
        status: 'pending_verification', // Initially pending until email verified
        isVerified: false,
        favorites: [],
        checkedOutBooks: [],
        createdAt: new Date().toISOString(),
        joinDate: new Date().toISOString().split('T')[0],
        lastLogin: null,
        emailVerificationToken: btoa(Math.random().toString()).substring(0, 32)
      };

      console.log('🎯 STEP 4: Patron record prepared:', newPatron);

      // Add to Firestore
      console.log('🎯 STEP 5: Adding to Firestore...');
      const docRef = await addDoc(collection(db, 'patrons'), newPatron);
      const patronWithId = { ...newPatron, id: docRef.id };

      console.log('🎯 STEP 5: Patron added to Firestore successfully:', patronWithId);

      // CRITICAL: Send welcome email with account details
      console.log('🎯 STEP 6: STARTING EMAIL SEND PROCESS...');
      console.log('🎯 STEP 6: Recipient email:', patronWithId.email);
      console.log('🎯 STEP 6: Generated password for email:', password);
      
      // Test EmailJS availability before sending
      console.log('🎯 STEP 6: Checking EmailJS availability...');
      if (!window.emailjs) {
        console.error('🎯 CRITICAL ERROR: EmailJS not available in window object');
        console.log('🎯 SOLUTION: Ensure EmailJS CDN script is loaded in public/index.html');
      } else {
        console.log('🎯 STEP 6: EmailJS is available, proceeding with send...');
      }
      
      let emailResult;
      try {
        emailResult = await emailService.sendPatronWelcomeEmail(patronWithId, password);
        console.log('🎯 STEP 7: Email service returned result:', emailResult);
      } catch (emailError) {
        console.error('🎯 STEP 7: Email service threw error:', emailError);
        emailResult = { 
          success: false, 
          error: emailError.message,
          method: 'service-error'
        };
      }
      
      if (!emailResult.success) {
        console.warn('🎯 STEP 8: Email failed but continuing with account creation');
        console.warn('🎯 STEP 8: Email error details:', emailResult);
        // Don't fail the account creation if email fails
      } else {
        console.log('🎯 STEP 8: Email sent successfully!', emailResult);
      }

      setIsLoading(false);
      
      const finalResult = {
        success: true,
        patron: patronWithId,
        password: password, // Return for admin display
        emailSent: emailResult.success,
        emailError: emailResult.success ? null : emailResult.error,
        emailMethod: emailResult.method || 'unknown'
      };
      
      console.log('🎯 FINAL: createPatronAccount completed successfully:', finalResult);
      
      return finalResult;
      
    } catch (error) {
      console.log('🎯 CRITICAL ERROR: createPatronAccount failed:', error);
      console.error('🎯 Error details:', error.stack);
      
      setIsLoading(false);
      return {
        success: false,
        error: error.message
      };
    }
  };

  // Enhanced test function for debugging
  const testEmailSetup = async () => {
    console.log('🧪 TESTING EMAIL SETUP...');
    
    // Test 1: Check EmailJS CDN
    console.log('Test 1: EmailJS CDN availability');
    if (!window.emailjs) {
      console.error('❌ EmailJS CDN not loaded');
      return { success: false, issue: 'cdn_not_loaded' };
    }
    console.log('✅ EmailJS CDN loaded');
    
    // Test 2: Check hardcoded values in emailService
    console.log('Test 2: EmailJS configuration (hardcoded values)');
    const testResult = emailService.testConnection();
    
    if (!testResult.success) {
      console.error('❌ EmailJS configuration issue');
      return { success: false, issue: 'config_issue', details: testResult };
    }
    console.log('✅ EmailJS configuration looks good');
    
    // Test 3: Try to initialize EmailJS
    console.log('Test 3: EmailJS initialization test');
    try {
      // This would need actual credentials to test properly
      console.log('📧 EmailJS initialization test skipped (need real credentials)');
    } catch (error) {
      console.error('❌ EmailJS initialization failed:', error);
      return { success: false, issue: 'init_failed', error: error.message };
    }
    
    console.log('🎉 All available email tests passed!');
    return { success: true };
  };

  // Login function (unchanged)
  const login = async (identifier, password) => {
    setIsLoading(true);
    
    try {
      // Query by email or card number
      const emailQuery = query(
        collection(db, 'patrons'), 
        where('email', '==', identifier.toLowerCase())
      );
      
      const cardQuery = query(
        collection(db, 'patrons'), 
        where('cardNumber', '==', identifier.toUpperCase())
      );

      let patronSnapshot = await getDocs(emailQuery);
      
      if (patronSnapshot.empty) {
        patronSnapshot = await getDocs(cardQuery);
      }

      if (patronSnapshot.empty) {
        throw new Error('Account not found');
      }

      const patronDoc = patronSnapshot.docs[0];
      const patronData = { id: patronDoc.id, ...patronDoc.data() };

      // Verify password
      const hashedPassword = hashPassword(password);
      if (patronData.password !== hashedPassword) {
        throw new Error('Invalid password');
      }

      // Update last login
      await updateDoc(doc(db, 'patrons', patronData.id), {
        lastLogin: new Date().toISOString()
      });

      // Set session
      setCurrentPatron(patronData);
      setIsAuthenticated(true);
      localStorage.setItem('currentPatron', JSON.stringify(patronData));

      setIsLoading(false);
      return { success: true, patron: patronData };
      
    } catch (error) {
      setIsLoading(false);
      console.error('Login error:', error);
      return { success: false, error: error.message };
    }
  };

  // Logout
  const logout = () => {
    setCurrentPatron(null);
    setIsAuthenticated(false);
    localStorage.removeItem('currentPatron');
  };

  // Change password
  const changePassword = async (currentPassword, newPassword) => {
    if (!currentPatron) {
      return { success: false, error: 'Not authenticated' };
    }
    
    setIsLoading(true);
    
    try {
      // Verify current password
      const hashedCurrentPassword = hashPassword(currentPassword);
      if (currentPatron.password !== hashedCurrentPassword) {
        throw new Error('Current password is incorrect');
      }

      // Update password
      const hashedNewPassword = hashPassword(newPassword);
      await updateDoc(doc(db, 'patrons', currentPatron.id), {
        password: hashedNewPassword
      });

      // Update local state
      const updatedPatron = { ...currentPatron, password: hashedNewPassword };
      setCurrentPatron(updatedPatron);
      localStorage.setItem('currentPatron', JSON.stringify(updatedPatron));

      setIsLoading(false);
      return { success: true };
      
    } catch (error) {
      setIsLoading(false);
      console.error('Password change error:', error);
      return { success: false, error: error.message };
    }
  };

  // Send password reset email
  const sendPasswordReset = async (email) => {
    setIsLoading(true);
    
    try {
      // Check if email exists
      const emailQuery = query(
        collection(db, 'patrons'), 
        where('email', '==', email.toLowerCase())
      );
      const emailSnapshot = await getDocs(emailQuery);
      
      if (emailSnapshot.empty) {
        throw new Error('Email address not found');
      }

      // Generate reset token (in production, use more secure method)
      const resetToken = btoa(Math.random().toString() + Date.now()).substring(0, 32);
      
      // Store reset token (expires in 1 hour)
      const patronDoc = emailSnapshot.docs[0];
      await updateDoc(doc(db, 'patrons', patronDoc.id), {
        resetToken: resetToken,
        resetTokenExpiry: new Date(Date.now() + 3600000).toISOString() // 1 hour
      });

      // Send reset email
      const emailResult = await emailService.sendPasswordResetEmail(email, resetToken);
      
      setIsLoading(false);
      
      if (!emailResult.success) {
        throw new Error('Failed to send reset email');
      }

      return { success: true };
      
    } catch (error) {
      setIsLoading(false);
      console.error('Password reset error:', error);
      return { success: false, error: error.message };
    }
  };

  // Add to favorites
  const addToFavorites = async (bookId) => {
    if (!currentPatron) return;
    
    try {
      const updatedFavorites = [...(currentPatron.favorites || []), bookId];
      await updateDoc(doc(db, 'patrons', currentPatron.id), {
        favorites: updatedFavorites
      });
      
      const updatedPatron = { ...currentPatron, favorites: updatedFavorites };
      setCurrentPatron(updatedPatron);
      localStorage.setItem('currentPatron', JSON.stringify(updatedPatron));
    } catch (error) {
      console.error('Error adding to favorites:', error);
    }
  };

  // Remove from favorites
  const removeFromFavorites = async (bookId) => {
    if (!currentPatron) return;
    
    try {
      const updatedFavorites = (currentPatron.favorites || []).filter(id => id !== bookId);
      await updateDoc(doc(db, 'patrons', currentPatron.id), {
        favorites: updatedFavorites
      });
      
      const updatedPatron = { ...currentPatron, favorites: updatedFavorites };
      setCurrentPatron(updatedPatron);
      localStorage.setItem('currentPatron', JSON.stringify(updatedPatron));
    } catch (error) {
      console.error('Error removing from favorites:', error);
    }
  };

  // Return book (patron self-return)
  const returnBook = async (bookId) => {
    if (!currentPatron) return;
    
    try {
      // Update checked out books list
      const updatedBooks = (currentPatron.checkedOutBooks || []).map(book => 
        book.id === bookId ? { ...book, status: 'returned', returnDate: new Date().toISOString() } : book
      );
      
      await updateDoc(doc(db, 'patrons', currentPatron.id), {
        checkedOutBooks: updatedBooks
      });
      
      const updatedPatron = { ...currentPatron, checkedOutBooks: updatedBooks };
      setCurrentPatron(updatedPatron);
      localStorage.setItem('currentPatron', JSON.stringify(updatedPatron));
    } catch (error) {
      console.error('Error returning book:', error);
    }
  };

  const value = {
    currentPatron,
    allPatrons,
    isAuthenticated,
    isLoading,
    createPatronAccount,
    login,
    logout,
    changePassword,
    sendPasswordReset,
    addToFavorites,
    removeFromFavorites,
    returnBook,
    testEmailSetup // Add test function to context
  };

  return (
    <PatronAuthContext.Provider value={value}>
      {children}
    </PatronAuthContext.Provider>
  );
};

// Add global test functions for easy debugging
if (typeof window !== 'undefined') {
  window.debugEmailSetup = () => {
    console.log('🧪 RUNNING EMAIL DEBUG CHECKS...');
    
    // Check 1: EmailJS CDN
    console.log('1. EmailJS CDN:', !!window.emailjs ? '✅ Loaded' : '❌ Missing');
    
    // Check 2: Email service functions
    console.log('2. Email service available:', typeof emailService?.sendPatronWelcomeEmail);
    
    // Instructions
    if (!window.emailjs) {
      console.log('🔧 FIX: Add to public/index.html:');
      console.log('<script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js"></script>');
    }
  };
}