import { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  onSnapshot, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  doc,
  orderBy 
} from 'firebase/firestore';
import { db } from '../firebase/config';

export const usePatrons = () => {
  const [patrons, setPatrons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const q = query(collection(db, 'patrons'), orderBy('name'));
    
    const unsubscribe = onSnapshot(q, 
      (snapshot) => {
        const patronsData = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setPatrons(patronsData);
        setLoading(false);
      },
      (error) => {
        setError(error.message);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, []);

  const addPatron = async (patronData) => {
    try {
      await addDoc(collection(db, 'patrons'), {
        ...patronData,
        joinDate: new Date().toISOString().split('T')[0],
        createdAt: new Date().toISOString()
      });
    } catch (error) {
      setError(error.message);
    }
  };

  const updatePatron = async (id, updates) => {
    try {
      await updateDoc(doc(db, 'patrons', id), updates);
    } catch (error) {
      setError(error.message);
    }
  };

  const deletePatron = async (id) => {
    try {
      await deleteDoc(doc(db, 'patrons', id));
    } catch (error) {
      setError(error.message);
    }
  };

  return {
    patrons,
    loading,
    error,
    addPatron,
    updatePatron,
    deletePatron
  };
};
