// src/services/emailService.js - Secure version using config file
import { EMAIL_CONFIG, LIBRARY_CONFIG } from '../config/config.js';

export const emailService = {
  sendPatronWelcomeEmail: async (patronData, password) => {
    console.log('🚀 Starting email send via CDN EmailJS...');
    console.log('📧 To:', patronData.email);
    
    try {
      // Check if EmailJS is loaded from CDN
      if (!window.emailjs) {
        console.error('❌ EmailJS not loaded from CDN');
        console.log('💡 Add this to public/index.html: <script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js"></script>');
        
        // Show email content for manual sending
        logEmailContent(patronData, password);
        return { success: false, error: 'EmailJS CDN not loaded', method: 'cdn-missing' };
      }
      
      console.log('✅ EmailJS CDN loaded successfully');
      
      // Use the configuration from config file
      const config = EMAIL_CONFIG;
      
      console.log('🔍 Configuration check:', {
        publicKey: config.publicKey && !config.publicKey.includes('YOUR_') ? 'Set (' + config.publicKey.substring(0, 8) + '...)' : 'Missing or placeholder',
        serviceId: config.serviceId && !config.serviceId.includes('YOUR_') ? 'Set (' + config.serviceId + ')' : 'Missing or placeholder',
        templateId: config.templateId && !config.templateId.includes('YOUR_') ? 'Set (' + config.templateId + ')' : 'Missing or placeholder'
      });
      
      // Check if config is missing or still has placeholders
      if (!config.publicKey || !config.serviceId || !config.templateId ||
          config.publicKey.includes('YOUR_') || config.serviceId.includes('YOUR_') || config.templateId.includes('YOUR_')) {
        console.log('⚠️ EmailJS configuration missing or using placeholders - logging email content instead');
        console.log('💡 Update src/config/config.js with your real EmailJS credentials');
        logEmailContent(patronData, password);
        return { 
          success: true, 
          method: 'fallback-logged',
          message: 'EmailJS not configured - check console for email content and update config.js'
        };
      }
      
      // Initialize EmailJS
      window.emailjs.init(config.publicKey);
      console.log('✅ EmailJS initialized with public key');
      
      // Prepare template parameters with proper formatting
      const templateParams = {
        // Basic recipient info
        to_name: patronData.name,
        to_email: patronData.email,
        
        // Patron details for the email
        patron_name: patronData.name,
        patron_email: patronData.email,
        patron_card_number: patronData.cardNumber,
        patron_password: password,
        membership_type: patronData.membershipType || 'Member',
        
        // Library information
        library_name: 'Ukrainian Library',
        library_website: LIBRARY_CONFIG.catalogUrl,
        login_url: LIBRARY_CONFIG.loginUrl,
        catalog_url: LIBRARY_CONFIG.catalogUrl,
        
        // Date and welcome messages
        created_date: new Date().toLocaleDateString('en-US', { 
          year: 'numeric', 
          month: 'long', 
          day: 'numeric' 
        }),
        
        // Bilingual welcome messages
        welcome_message_uk: 'Ласкаво просимо до Української Бібліотеки! Ваш обліковий запис успішно створено.',
        welcome_message_en: 'Welcome to Ukrainian Library! Your account has been successfully created.',
        
        // Instructions in both languages
        instructions_uk: 'Ви можете увійти в систему, використовуючи наведені вище дані. Рекомендуємо змінити пароль після першого входу. Ви також можете оновити свою електронну пошту та інші дані в налаштуваннях облікового запису.',
        instructions_en: 'You can sign in using the credentials above. We recommend changing your password after first login. You can also update your email and other details in your account settings.',
        
        // Security note
        security_note_uk: 'Зберігайте свої дані для входу в безпеці. При виникненні проблем зв\'яжіться з персоналом бібліотеки.',
        security_note_en: 'Keep your login credentials secure. Contact our library staff if you have any issues.',
        
        // Next steps
        next_steps_uk: 'Увійдіть в систему та почніть користуватися нашою колекцією української літератури!',
        next_steps_en: 'Sign in and start exploring our Ukrainian literature collection!'
      };
      
      console.log('📋 Template parameters prepared:', {
        recipient: templateParams.to_email,
        variables: Object.keys(templateParams).length + ' parameters'
      });
      
      // Send email using CDN EmailJS
      console.log('📤 Sending formatted welcome email...');
      const response = await window.emailjs.send(
        config.serviceId, 
        config.templateId, 
        templateParams
      );
      
      console.log('✅ Email sent successfully via CDN!');
      console.log('📨 EmailJS Response:', response);
      
      return { 
        success: true, 
        response,
        method: 'emailjs-cdn',
        message: 'Welcome email sent successfully with proper formatting'
      };
      
    } catch (error) {
      console.error('❌ Email sending failed:', error.message);
      console.error('📍 Full error:', error);
      
      // Log email content as fallback
      console.log('🔄 Logging email content for manual sending...');
      logEmailContent(patronData, password);
      
      return { 
        success: false, 
        error: error.message,
        method: 'failed-with-fallback',
        fallback: true
      };
    }
  },

  // Test EmailJS connection
  testConnection: () => {
    console.log('🧪 Testing EmailJS CDN connection...');
    
    if (window.emailjs) {
      console.log('✅ EmailJS CDN is available');
      console.log('🔧 EmailJS methods:', Object.keys(window.emailjs));
      
      const config = EMAIL_CONFIG;
      const configStatus = {
        publicKey: config.publicKey && !config.publicKey.includes('YOUR_') ? 'Set (' + config.publicKey.substring(0, 8) + '...)' : 'Missing or placeholder',
        serviceId: config.serviceId && !config.serviceId.includes('YOUR_') ? 'Set (' + config.serviceId + ')' : 'Missing or placeholder',
        templateId: config.templateId && !config.templateId.includes('YOUR_') ? 'Set (' + config.templateId + ')' : 'Missing or placeholder'
      };
      
      console.log('⚙️ Configuration status:', configStatus);
      
      return { success: true, available: true, config: configStatus };
    } else {
      console.log('❌ EmailJS CDN not loaded');
      console.log('💡 Add script tag to public/index.html:');
      console.log('<script src="https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js"></script>');
      
      return { success: false, available: false, error: 'CDN not loaded' };
    }
  },

  // Send password reset email
  sendPasswordResetEmail: async (email, resetToken) => {
    console.log('🔐 Sending password reset email to:', email);
    
    if (!window.emailjs) {
      console.log('❌ EmailJS CDN not available for password reset');
      return { success: false, error: 'EmailJS not loaded' };
    }
    
    try {
      const templateParams = {
        to_email: email,
        reset_link: `${LIBRARY_CONFIG.catalogUrl}#reset-password?token=${resetToken}`,
        library_name: 'Ukrainian Library',
        catalog_url: LIBRARY_CONFIG.catalogUrl,
        expiration_time: new Date(Date.now() + 3600000).toLocaleString()
      };
      
      // Use the service ID from configuration
      const response = await window.emailjs.send(
        EMAIL_CONFIG.serviceId,
        'password_reset_template',       // You'll need to create this template
        templateParams
      );
      
      console.log('✅ Password reset email sent:', response);
      return { success: true, response };
      
    } catch (error) {
      console.error('❌ Password reset email failed:', error);
      return { success: false, error: error.message };
    }
  }
};

